insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-J1', 'ANG-01', 'Junior', 'mc', '¿Qué decorador convierte una clase en un componente?', null, '@Component', array['@Injectable', '@NgModule', '@Directive']::text[], '@Component añade la plantilla, los estilos y el selector a la clase.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-J2', 'ANG-01', 'Junior', 'mc', '¿Qué tipo de binding es `[disabled]="isSaving"`?', null, 'Property binding (del componente a la vista)', array['Event binding (de la vista al componente)', 'Two-way binding', 'Interpolación']::text[], 'Los corchetes enlazan una propiedad del DOM con un valor del componente. Los paréntesis son eventos y `[( )]` es two-way.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-J3', 'ANG-01', 'Junior', 'fill', 'Para enviar datos de un hijo a su padre se usa un ___ con un EventEmitter (o la función output()).', null, '@Output', array['@Input', '@ViewChild', '@HostListener']::text[], '@Input recibe datos del padre; @Output los emite hacia arriba.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-J4', 'ANG-01', 'Junior', 'open', '¿Qué es un componente standalone y qué ventajas tiene?', 'What is a standalone component and what are its advantages?', null, '{}'::text[], null, null, null, 'no NgModule needed; imports declared in the component itself; less boilerplate; easier lazy loading with loadComponent; default in recent Angular versions', 'A standalone component doesn''t need to be declared in an NgModule. It lists its own dependencies in the imports array, so it''s easier to see what it uses. It means less boilerplate, it''s easier to lazy load with loadComponent, and it''s the default way to build apps in recent Angular versions.', 'Un componente standalone no necesita declararse en un NgModule. Declara sus propias dependencias en el array imports, así que se ve enseguida qué usa. Supone menos código repetitivo, es más fácil cargarlo de forma diferida con loadComponent y es la forma por defecto de crear aplicaciones en las versiones recientes de Angular.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-M1', 'ANG-01', 'Mid', 'mc', '¿Cuál es la sintaxis del nuevo control flow para recorrer una lista?', null, '@for (item of items; track item.id) { … }', array['*ngFor="let item of items" track item.id', '@each (item in items) { … }', '<for items="items">']::text[], 'El control flow integrado (@if, @for, @switch) sustituye a las directivas estructurales. En @for, `track` es obligatorio.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-M2', 'ANG-01', 'Mid', 'mc', 'Formularios reactivos frente a template-driven: ¿qué es cierto?', null, 'Los reactivos definen el modelo en TypeScript (FormGroup, FormControl) y son más fáciles de testear y validar dinámicamente', array['Los template-driven son más escalables para formularios grandes', 'Los reactivos no permiten validadores personalizados', 'Son lo mismo con distinta sintaxis']::text[], 'En los reactivos el formulario vive en el componente: control total, tipado y tests sin depender del DOM.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-M3', 'ANG-01', 'Mid', 'fill', 'Para mostrar en un componente el contenido que le pasa el padre entre sus etiquetas se usa ___.', null, '<ng-content>', array['<ng-template>', '<ng-container>', '<router-outlet>']::text[], 'Es la proyección de contenido. Con el atributo select puedes tener varios huecos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-M4', 'ANG-01', 'Mid', 'open', '¿Cómo diseñarías un componente reutilizable, por ejemplo una tabla, para usarlo en varias pantallas?', 'How would you design a reusable component, for example a table, to use across several screens?', null, '{}'::text[], null, null, null, 'clear inputs/outputs API; presentational (dumb) component without business logic; content projection or ng-template for custom cells; OnPush; typed inputs; accessibility; documented and tested', 'I''d make it a presentational component: it receives data and configuration through inputs and emits events like sort or row click through outputs, without calling services itself. For custom cells I''d accept templates with ng-template, so each screen decides how to render them. I''d use OnPush, strong typing for the column config, and make sure it''s accessible. Then I''d document the API and write tests for the main behaviours.', 'Lo haría como un componente de presentación: recibe los datos y la configuración por inputs y emite eventos, como ordenar o hacer clic en una fila, por outputs, sin llamar a servicios. Para celdas personalizadas aceptaría plantillas con ng-template, para que cada pantalla decida cómo pintarlas. Usaría OnPush, tiparía bien la configuración de columnas y cuidaría la accesibilidad. Después documentaría su API y le haría tests de los comportamientos principales.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-S1', 'ANG-01', 'Senior', 'mc', 'En una app grande, ¿cuál es una buena forma de organizar el código?', null, 'Por funcionalidades (feature folders) con límites claros, librerías compartidas y carga perezosa', array['Una carpeta por tipo de archivo: todos los componentes juntos, todos los servicios juntos', 'Todo en un único módulo para evitar imports', 'Un repositorio por componente']::text[], 'Agrupar por dominio escala mejor. Herramientas como Nx ayudan a imponer los límites entre módulos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-S2', 'ANG-01', 'Senior', 'mc', '¿Qué aportan los microfrontends y cuál es su principal coste?', null, 'Despliegues independientes por equipo, a cambio de más complejidad (versionado, dependencias compartidas, consistencia visual)', array['Siempre mejoran el rendimiento', 'Eliminan la necesidad de un design system', 'Solo sirven para apps pequeñas']::text[], 'Tienen sentido con varios equipos autónomos. Para un solo equipo suelen ser sobreingeniería.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-S3', 'ANG-01', 'Senior', 'mc', 'Vas a migrar una app grande de NgModules a standalone. ¿Cómo lo harías?', null, 'De forma incremental, empezando por las hojas, con el schematic oficial de migración y tests en cada paso', array['De golpe en una rama larga', 'Reescribiendo la app desde cero', 'No se puede convivir con ambos sistemas']::text[], 'Standalone y NgModules conviven, así que se puede migrar poco a poco sin parar el desarrollo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-01-S4', 'ANG-01', 'Senior', 'open', 'Cuéntame cómo decidirías la arquitectura frontend de un proyecto nuevo.', 'Tell me how you would decide the frontend architecture for a new project.', null, '{}'::text[], null, null, null, 'start from requirements and team size; folder/feature structure; state management choice; design system; routing and lazy loading; API layer; testing strategy; CI and linting; document decisions (ADRs); keep it simple and evolve', 'I''d start from the requirements and the team: how big the app will get and how many people will work on it. Then I''d define a feature-based structure with lazy-loaded routes, a shared UI library or design system, and a clear API layer. For state I''d begin with signals and services, and only add something like NgRx if the complexity justifies it. I''d set up linting, a testing strategy and CI from day one, and write down the key decisions so the team understands why.', 'Empezaría por los requisitos y el equipo: cuánto va a crecer la aplicación y cuántas personas van a trabajar en ella. Después definiría una estructura por funcionalidades con rutas de carga diferida, una librería de UI o design system compartido y una capa clara de acceso a la API. Para el estado empezaría con signals y servicios, y solo añadiría algo como NgRx si la complejidad lo justifica. Montaría linting, una estrategia de testing y CI desde el primer día, y dejaría por escrito las decisiones clave para que el equipo entienda el porqué.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-J1', 'ANG-02', 'Junior', 'mc', '¿Qué hace Zone.js en una app Angular clásica?', null, 'Avisa a Angular cuando termina un evento asíncrono para que revise la vista', array['Gestiona las rutas', 'Compila las plantillas', 'Guarda el estado global']::text[], 'Parchea clics, timers y peticiones HTTP. Las apps nuevas pueden funcionar sin él (zoneless).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-J2', 'ANG-02', 'Junior', 'mc', '¿Para qué sirve el pipe `async`?', null, 'Se suscribe a un observable en la plantilla y se desuscribe solo al destruirse el componente', array['Hace la petición HTTP más rápida', 'Convierte valores a mayúsculas', 'Ejecuta código en segundo plano']::text[], 'Evita fugas de memoria por suscripciones olvidadas y funciona bien con OnPush.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-J3', 'ANG-02', 'Junior', 'fill', 'En @for, la expresión ___ permite a Angular reutilizar los elementos del DOM en vez de recrearlos.', null, 'track', array['key', 'index', 'trackBy()']::text[], 'Con un identificador estable, Angular solo toca los elementos que cambian.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-J4', 'ANG-02', 'Junior', 'open', '¿Qué es la detección de cambios en Angular, explicado de forma sencilla?', 'What is change detection in Angular, in simple terms?', null, '{}'::text[], null, null, null, 'process that keeps the view in sync with component data; triggered after events/async tasks; checks bindings top-down; Default vs OnPush; signals', 'Change detection is how Angular keeps the screen in sync with the data. When something happens, like a click or an HTTP response, Angular goes through the components and checks if any value used in the template has changed, and if so it updates the DOM. You can make it more efficient with the OnPush strategy or with signals.', 'La detección de cambios es cómo Angular mantiene la pantalla sincronizada con los datos. Cuando pasa algo, como un clic o la respuesta de una petición HTTP, Angular recorre los componentes, comprueba si ha cambiado algún valor usado en la plantilla y, si es así, actualiza el DOM. Se puede hacer más eficiente con la estrategia OnPush o con signals.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-M1', 'ANG-02', 'Mid', 'mc', 'Con OnPush, ¿qué NO provoca que se revise el componente?', null, 'Mutar una propiedad de un objeto @Input sin cambiar la referencia', array['Un nuevo objeto en un @Input', 'Un evento de la propia plantilla', 'Un signal leído en la plantilla que cambia']::text[], 'OnPush compara referencias. Mutar no cambia la referencia, así que hay que trabajar con datos inmutables o signals.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-M2', 'ANG-02', 'Mid', 'mc', '¿Diferencia entre `markForCheck()` y `detectChanges()`?', null, 'markForCheck marca el componente y sus ancestros para el próximo ciclo; detectChanges lo revisa al momento', array['Son idénticos', 'detectChanges solo funciona con Default', 'markForCheck destruye la vista']::text[], 'markForCheck es lo habitual con OnPush; detectChanges se usa en casos puntuales o en tests.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-M3', 'ANG-02', 'Mid', 'mc', 'Una lista de 10.000 filas va lenta. ¿Qué es lo más efectivo?', null, 'Virtual scrolling (CDK) más track y OnPush', array['Aumentar la memoria del navegador', 'Pasar todo a setTimeout', 'Usar más pipes impuros']::text[], 'El virtual scroll solo pinta las filas visibles, así el DOM sigue pequeño.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-M4', 'ANG-02', 'Mid', 'open', 'La aplicación va lenta. ¿Cómo investigarías el problema de rendimiento?', 'The application is slow. How would you investigate the performance problem?', null, '{}'::text[], null, null, null, 'measure first: Angular DevTools profiler, Chrome Performance tab, Lighthouse; identify cause: too many change detection cycles, heavy templates/functions in templates, large bundles, big lists; fixes: OnPush/signals, track, virtual scroll, lazy loading, defer blocks; measure again', 'First I''d measure instead of guessing. I''d use the Angular DevTools profiler to see which components are checked too often, and the Chrome Performance tab and Lighthouse for loading issues. Typical causes are function calls in templates, Default change detection everywhere, big lists, or large bundles. Depending on the cause, I''d apply OnPush or signals, add track, virtual scrolling, lazy loading or defer blocks, and then measure again to confirm the improvement.', 'Primero mediría en vez de suponer. Usaría el profiler de Angular DevTools para ver qué componentes se revisan demasiado, y la pestaña Performance de Chrome y Lighthouse para los problemas de carga. Las causas típicas son llamadas a funciones en las plantillas, detección Default en todas partes, listas muy grandes o bundles pesados. Según la causa, aplicaría OnPush o signals, track, virtual scroll, lazy loading o bloques defer, y volvería a medir para confirmar la mejora.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-S1', 'ANG-02', 'Senior', 'mc', '¿Qué implica pasar una app a zoneless?', null, 'La detección de cambios la disparan signals, eventos de plantilla y markForCheck; el código que dependía de Zone.js para refrescar la vista hay que adaptarlo', array['No cambia nada', 'Desaparece la necesidad de OnPush y de signals', 'Solo afecta a los tests']::text[], 'Sin Zone.js se gana en rendimiento y en tamaño, pero los setTimeout o librerías externas ya no refrescan la vista solos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-S2', 'ANG-02', 'Senior', 'mc', '¿Para qué sirven los bloques `@defer`?', null, 'Cargar de forma diferida partes de la plantilla y su código según un disparador (viewport, interacción, idle…)', array['Retrasar la detección de cambios', 'Diferir peticiones HTTP', 'Ejecutar código en un Web Worker']::text[], 'Reducen el bundle inicial sin crear rutas nuevas, por ejemplo para un gráfico pesado bajo el pliegue.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-S3', 'ANG-02', 'Senior', 'mc', '¿Qué aporta el SSR con hidratación en Angular?', null, 'Primer pintado más rápido y mejor SEO; la hidratación reutiliza el DOM del servidor en vez de recrearlo', array['Elimina el JavaScript del cliente', 'Solo sirve para apps sin datos', 'Sustituye al lazy loading']::text[], 'Hay que cuidar el código que usa APIs del navegador (window, localStorage) porque en el servidor no existen.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-02-S4', 'ANG-02', 'Senior', 'open', '¿Cómo establecerías y vigilarías un presupuesto de rendimiento en un equipo?', 'How would you set and monitor a performance budget in a team?', null, '{}'::text[], null, null, null, 'define metrics (Core Web Vitals, bundle size); budgets in angular.json; Lighthouse CI in the pipeline; real user monitoring; dashboards; review in PRs; fail the build when exceeded; culture', 'I''d agree on a few metrics with the team, like bundle size and Core Web Vitals such as LCP and INP. Then I''d make them automatic: size budgets in angular.json that fail the build, and Lighthouse CI in the pipeline. For real users I''d add monitoring to see the field data. And I''d make performance part of code reviews, so regressions are caught early instead of fixed later.', 'Acordaría con el equipo unas pocas métricas, como el tamaño del bundle y las Core Web Vitals, por ejemplo LCP e INP. Después las automatizaría: presupuestos de tamaño en angular.json que rompan el build y Lighthouse CI en el pipeline. Para los usuarios reales añadiría monitorización y vería los datos de campo. Y haría del rendimiento parte de las code reviews, para detectar empeoramientos pronto en lugar de arreglarlos después.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-J1', 'ANG-03', 'Junior', 'mc', '¿Qué es un Observable?', null, 'Un flujo de valores que llegan a lo largo del tiempo y al que te suscribes', array['Una promesa que siempre devuelve un valor', 'Una variable global', 'Un tipo de componente']::text[], 'A diferencia de una Promise, puede emitir muchos valores y es perezoso: no hace nada hasta que alguien se suscribe.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-J2', 'ANG-03', 'Junior', 'mc', '¿Qué operador transforma cada valor emitido?', null, 'map', array['filter', 'take', 'tap']::text[], 'map transforma, filter descarta, take limita y tap sirve para efectos secundarios como logs.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-J3', 'ANG-03', 'Junior', 'fill', 'Para no tener fugas de memoria hay que ___ de los observables que no se completan solos.', null, 'desuscribirse', array['suscribirse dos veces', 'reiniciar', 'compilar']::text[], 'Formas habituales: pipe async, takeUntilDestroyed() o toSignal().', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-J4', 'ANG-03', 'Junior', 'open', '¿Diferencia entre una Promise y un Observable?', 'What''s the difference between a Promise and an Observable?', null, '{}'::text[], null, null, null, 'promise: single value, eager, not cancellable; observable: multiple values over time, lazy, cancellable via unsubscribe, operators', 'A Promise gives you one value and starts running as soon as you create it, and you can''t cancel it. An Observable can emit many values over time, it''s lazy so nothing happens until you subscribe, and you can cancel it by unsubscribing. Observables also come with operators like map, filter or switchMap to transform the stream.', 'Una Promise devuelve un único valor, empieza a ejecutarse en cuanto la creas y no se puede cancelar. Un Observable puede emitir muchos valores a lo largo del tiempo, es perezoso, así que no hace nada hasta que te suscribes, y se cancela desuscribiéndote. Además, los Observables tienen operadores como map, filter o switchMap para transformar el flujo.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-M1', 'ANG-03', 'Mid', 'mc', 'Buscador: solo importa la última petición. ¿Qué operador?', null, 'switchMap', array['mergeMap', 'concatMap', 'exhaustMap']::text[], 'switchMap cancela la petición anterior al llegar un valor nuevo. Se combina con debounceTime y distinctUntilChanged.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-M2', 'ANG-03', 'Mid', 'mc', 'Botón de pagar: ignorar clics mientras la primera petición está en curso.', null, 'exhaustMap', array['switchMap', 'mergeMap', 'concatMap']::text[], 'exhaustMap ignora lo que llega mientras hay algo en marcha.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-M3', 'ANG-03', 'Mid', 'mc', '¿Qué hace `combineLatest`?', null, 'Emite cada vez que cualquiera emite, con el último valor de cada uno (cuando todos han emitido al menos una vez)', array['Espera a que todos se completen y emite una vez', 'Emite los valores en orden de suscripción', 'Cancela los demás observables']::text[], 'forkJoin es el que espera a que todos terminen; combineLatest va combinando en vivo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-M4', 'ANG-03', 'Mid', 'open', '¿Cómo implementarías un buscador con autocompletado usando RxJS?', 'How would you implement a search box with autocomplete using RxJS?', null, '{}'::text[], null, null, null, 'valueChanges or input events; debounceTime; distinctUntilChanged; filter min length; switchMap to HTTP; catchError so the stream doesn''t die; loading state; async pipe or toSignal', 'I''d take the valueChanges of the input, then use debounceTime to wait a few hundred milliseconds, distinctUntilChanged to skip repeated terms, and filter out very short queries. Then switchMap to the HTTP call, so older requests are cancelled. Inside the switchMap I''d add catchError, so one failed request doesn''t kill the whole stream. Finally I''d expose the results with the async pipe or toSignal.', 'Tomaría los valueChanges del input y aplicaría debounceTime para esperar unos cientos de milisegundos, distinctUntilChanged para no repetir términos y un filtro para descartar búsquedas muy cortas. Después, switchMap hacia la llamada HTTP, para cancelar las peticiones anteriores. Dentro del switchMap pondría catchError, para que un error no rompa todo el flujo. Por último, mostraría los resultados con el pipe async o con toSignal.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-S1', 'ANG-03', 'Senior', 'mc', '¿Qué es cierto sobre los observables hot y cold?', null, 'Un cold crea su productor por cada suscriptor (p. ej. HTTP); un hot comparte un productor ya existente (p. ej. eventos del DOM, Subjects)', array['Hot significa que da error', 'Cold significa que ya está completado', 'No hay diferencia práctica']::text[], 'Por eso cada suscripción a un http.get repite la petición, salvo que la compartas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-S2', 'ANG-03', 'Senior', 'mc', '¿Qué hace `shareReplay({ bufferSize: 1, refCount: true })`?', null, 'Comparte una única ejecución entre suscriptores, repite el último valor y se desuscribe del origen cuando no queda nadie', array['Repite la petición en cada suscripción', 'Guarda todos los valores para siempre', 'Convierte el observable en una promesa']::text[], 'Con refCount: false la suscripción al origen se mantiene viva aunque no haya suscriptores, lo que puede dejar fugas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-S3', 'ANG-03', 'Senior', 'mc', '¿Cuál es un problema típico de anidar `subscribe` dentro de otro `subscribe`?', null, 'Pierdes la cancelación y el control de errores, y aparecen condiciones de carrera y fugas', array['Es más rápido', 'Angular lo prohíbe en compilación', 'No hay ningún problema']::text[], 'La solución es aplanar con operadores como switchMap, concatMap o mergeMap.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-03-S4', 'ANG-03', 'Senior', 'open', '¿Cómo gestionarías los errores y los reintentos en flujos RxJS de una app grande?', 'How would you handle errors and retries in RxJS streams in a large app?', null, '{}'::text[], null, null, null, 'catchError at the right level so the outer stream survives; retry with delay/backoff only for idempotent requests; global HTTP interceptor for common errors; user feedback; logging/monitoring; finalize for cleanup; don''t swallow errors silently', 'I''d handle errors at the right level: inside the inner observable with catchError, so the main stream keeps working. For network errors I''d use retry with a delay and a limit, but only for idempotent requests. Common cases like 401 or 500 go into an HTTP interceptor, with a consistent message for the user. And I''d always log errors to a monitoring tool instead of swallowing them silently.', 'Gestionaría los errores en el nivel adecuado: dentro del observable interno con catchError, para que el flujo principal siga funcionando. Para errores de red usaría retry con espera y límite, pero solo en peticiones idempotentes. Los casos comunes, como un 401 o un 500, irían a un interceptor HTTP con un mensaje coherente para el usuario. Y siempre registraría los errores en una herramienta de monitorización en lugar de ocultarlos.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-J1', 'ANG-04', 'Junior', 'mc', '¿Cómo lees el valor de un signal `count`?', null, 'count()', array['count.value', 'count.get', 'await count']::text[], 'Un signal es una función: se lee llamándola. Para escribir: set() o update().', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-J2', 'ANG-04', 'Junior', 'fill', 'Para cambiar un signal a partir de su valor anterior se usa ___.', null, 'update()', array['set()', 'next()', 'patch()']::text[], 'set() pone un valor nuevo; update() recibe el valor actual y devuelve el nuevo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-J3', 'ANG-04', 'Junior', 'mc', '¿Qué es `computed()`?', null, 'Un signal de solo lectura derivado de otros, que se recalcula cuando cambian', array['Un signal que hace peticiones HTTP', 'Un efecto secundario', 'Un observable']::text[], 'Por ejemplo: total = computed(() => items().length).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-J4', 'ANG-04', 'Junior', 'open', '¿Qué son los signals y por qué los ha añadido Angular?', 'What are signals and why did Angular add them?', null, '{}'::text[], null, null, null, 'reactive values that notify consumers when they change; set/update, computed, effect; fine-grained change detection; simpler than RxJS for state; path to zoneless', 'Signals are reactive values: when a signal changes, everything that reads it, like a template or a computed value, is notified. You write them with set or update and derive values with computed. Angular added them because they give fine-grained change detection, they''re simpler than RxJS for local state, and they make apps without Zone.js possible.', 'Los signals son valores reactivos: cuando un signal cambia, todo lo que lo lee, como una plantilla o un valor computed, se entera. Se escriben con set o update y se derivan valores con computed. Angular los añadió porque permiten una detección de cambios mucho más precisa, son más sencillos que RxJS para el estado local y hacen posibles las aplicaciones sin Zone.js.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-M1', 'ANG-04', 'Mid', 'mc', '¿Para qué se usa `effect()`?', null, 'Para efectos secundarios cuando cambian signals (logs, guardar en localStorage, sincronizar con una API externa)', array['Para derivar valores', 'Para sustituir a computed', 'Para hacer el binding de la plantilla']::text[], 'No se debe usar para copiar un signal en otro: para eso está computed (o linkedSignal).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-M2', 'ANG-04', 'Mid', 'mc', '¿Qué hacen `input()` y `model()` frente a @Input?', null, 'input() expone el input como signal de solo lectura; model() crea un input con two-way binding escribible', array['Son alias de @Output', 'Solo funcionan en NgModules', 'Sustituyen a los servicios']::text[], 'Al ser signals, puedes usarlos directamente en computed sin ngOnChanges.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-M3', 'ANG-04', 'Mid', 'mc', '¿Dónde guardarías un estado compartido sencillo entre varios componentes?', null, 'En un servicio inyectable con signals privados y métodos para modificarlos', array['En variables globales de window', 'En el localStorage leído en cada render', 'En un @Input que pase por toda la jerarquía']::text[], 'Exponer signals de solo lectura (asReadonly) evita que cualquiera modifique el estado sin pasar por el servicio.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-M4', 'ANG-04', 'Mid', 'open', '¿Cuándo usarías signals y cuándo observables?', 'When would you use signals and when would you use observables?', null, '{}'::text[], null, null, null, 'signals: synchronous state, derived values, templates; observables: async streams over time, HTTP, websockets, complex operators; interop with toSignal/toObservable', 'I use signals for state: the selected item, a filter, a loading flag, and derived values with computed. I use observables for things that happen over time and need coordination, like HTTP, websockets, or a search with debounceTime and switchMap. They work well together: I build the async flow with RxJS and expose the result to the template with toSignal.', 'Uso signals para el estado: el elemento seleccionado, un filtro, un indicador de carga, y valores derivados con computed. Uso observables para lo que ocurre a lo largo del tiempo y necesita coordinación, como HTTP, websockets o un buscador con debounceTime y switchMap. Se combinan bien: construyo el flujo asíncrono con RxJS y expongo el resultado en la plantilla con toSignal.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-S1', 'ANG-04', 'Senior', 'mc', '¿Cuándo tendría sentido NgRx (o una store similar)?', null, 'Cuando muchas partes de la app comparten estado complejo y conviene un flujo predecible, trazable y con herramientas de depuración', array['Siempre, en cualquier app', 'Nunca, los signals lo sustituyen del todo', 'Solo para formularios']::text[], 'Para estado sencillo, un servicio con signals basta. NgRx Signal Store es una opción intermedia.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-S2', 'ANG-04', 'Senior', 'mc', '¿Qué ventaja tiene que el estado se modifique solo desde un servicio con métodos claros?', null, 'Un único punto de cambio: más fácil de depurar, testear y razonar', array['Es más rápido de escribir', 'Evita usar TypeScript', 'Permite mutar desde cualquier componente']::text[], 'Es el principio de la mayoría de librerías de estado: lectura libre, escritura controlada.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-S3', 'ANG-04', 'Senior', 'fill', 'Para crear un signal que depende de otro pero que también puede editarse a mano se usa ___.', null, 'linkedSignal()', array['computed()', 'effect()', 'toSignal()']::text[], 'Útil, por ejemplo, para una opción seleccionada que se reinicia cuando cambia la lista.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-04-S4', 'ANG-04', 'Senior', 'open', '¿Cómo diseñarías la gestión del estado de una app mediana-grande?', 'How would you design state management for a medium-to-large app?', null, '{}'::text[], null, null, null, 'classify state: local UI, shared feature, server/cache, URL; keep state close to where it''s used; services with signals; server state with caching; store (NgRx) only if needed; immutability; single source of truth; testing', 'First I''d separate the types of state: local UI state stays in the component, shared feature state goes into services with signals, server data needs caching and loading/error handling, and some state belongs in the URL. I''d keep each piece as close as possible to where it''s used. Only if many features share complex state would I add a store like NgRx. In all cases: one source of truth, immutable updates and good tests.', 'Primero separaría los tipos de estado: el de UI local se queda en el componente, el compartido de una funcionalidad va en servicios con signals, los datos del servidor necesitan caché y gestión de carga y errores, y parte del estado pertenece a la URL. Mantendría cada pieza lo más cerca posible de donde se usa. Solo si muchas funcionalidades comparten un estado complejo añadiría una store como NgRx. En todos los casos: una única fuente de verdad, actualizaciones inmutables y buenos tests.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-J1', 'ANG-05', 'Junior', 'fill', 'En la plantilla, las rutas se pintan dentro de ___.', null, '<router-outlet>', array['<ng-content>', '<router-view>', '<app-root>']::text[], 'routerLink navega y router-outlet es el hueco donde se pinta la ruta activa.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-J2', 'ANG-05', 'Junior', 'mc', '¿Cómo lees el parámetro `id` de la ruta `/users/:id`?', null, 'Con ActivatedRoute (paramMap) o con un input del componente si está activado withComponentInputBinding', array['Con window.location.id', 'Con localStorage', 'Con un @Output']::text[], 'Con withComponentInputBinding() el parámetro llega directamente como input.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-J3', 'ANG-05', 'Junior', 'mc', '¿Qué hace `providedIn: ''root''`?', null, 'Crea una única instancia compartida en toda la app y permite tree-shaking', array['Crea una instancia por componente', 'Solo funciona en AppComponent', 'Obliga a declararlo en cada módulo']::text[], 'Si nadie lo inyecta, el build lo elimina.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-J4', 'ANG-05', 'Junior', 'open', '¿Qué es la inyección de dependencias y por qué es útil?', 'What is dependency injection and why is it useful?', null, '{}'::text[], null, null, null, 'class receives dependencies instead of creating them; Angular injector provides instances; loose coupling; easy to test with mocks; singletons/shared instances', 'Dependency injection means a class receives what it needs instead of creating it itself. In Angular, the injector creates the services and gives them to components through the constructor or the inject function. It reduces coupling, makes it easy to share one instance, and above all makes testing easier, because you can replace a real service with a fake one.', 'La inyección de dependencias significa que una clase recibe lo que necesita en lugar de crearlo ella misma. En Angular, el inyector crea los servicios y se los da a los componentes por el constructor o con la función inject. Reduce el acoplamiento, facilita compartir una única instancia y, sobre todo, facilita los tests, porque puedes sustituir un servicio real por uno falso.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-M1', 'ANG-05', 'Mid', 'mc', '¿Cómo haces lazy loading de un componente standalone?', null, 'loadComponent: () => import(''./admin.component'').then(m => m.AdminComponent)', array['component: AdminComponent, lazy: true', 'Importándolo arriba en app.routes.ts', 'children: [AdminComponent]']::text[], 'El import() dinámico genera un chunk aparte que solo se descarga al entrar en la ruta.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-M2', 'ANG-05', 'Mid', 'mc', 'Dentro de un interceptor, ¿cómo añades una cabecera?', null, 'next(req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }))', array['req.headers.set(...) y devolver req', 'Modificar window.fetch', 'Añadirla en cada servicio']::text[], 'HttpRequest es inmutable: hay que clonarla.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-M3', 'ANG-05', 'Mid', 'mc', 'Un CanActivateFn quiere mandar al usuario a /login. ¿Qué devuelve?', null, 'router.createUrlTree([''/login''])', array['false y luego router.navigate', 'Un componente LoginComponent', 'Un error']::text[], 'Devolver un UrlTree es la forma recomendada: evita navegaciones dobles.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-M4', 'ANG-05', 'Mid', 'open', '¿Cómo añadirías un token a todas las peticiones HTTP y qué harías ante un 401?', 'How would you add a token to every HTTP request, and what would you do on a 401?', null, '{}'::text[], null, null, null, 'functional interceptor with withInterceptors; inject auth service; clone with setHeaders; skip public URLs; catchError 401: refresh token and retry once, else logout and redirect', 'I''d write a functional interceptor and register it with provideHttpClient and withInterceptors. It injects the auth service, clones the request and adds the Authorization header, skipping public endpoints like login. On the response I add catchError: if I get a 401, I try to refresh the token once and retry; if that fails, I clear the session and redirect to the login page.', 'Escribiría un interceptor funcional y lo registraría con provideHttpClient y withInterceptors. El interceptor inyecta el servicio de autenticación, clona la petición y añade la cabecera Authorization, salvo en endpoints públicos como el login. En la respuesta añado catchError: si llega un 401, intento refrescar el token una vez y repito la petición; si falla, cierro la sesión y redirijo a la pantalla de login.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-S1', 'ANG-05', 'Senior', 'mc', '¿Qué jerarquías de inyectores existen en Angular?', null, 'Environment injectors (raíz, rutas lazy) y element injectors (componentes y directivas)', array['Solo hay un inyector global', 'Un inyector por petición HTTP', 'Los inyectores solo existen en tests']::text[], 'Proveer un servicio en un componente crea una instancia nueva para ese subárbol.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-S2', 'ANG-05', 'Senior', 'mc', '¿Para qué sirve un InjectionToken?', null, 'Para inyectar valores que no son clases, como configuración o funciones', array['Para cifrar tokens JWT', 'Para crear rutas', 'Para sustituir a los guards']::text[], 'Ejemplo: un token API_URL con el valor que cambia por entorno.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-S3', 'ANG-05', 'Senior', 'mc', '¿Qué estrategia de precarga carga los módulos lazy en segundo plano tras el arranque?', null, 'PreloadAllModules (o una estrategia propia)', array['NoPreloading', 'EagerLoading', 'Server preloading']::text[], 'Una estrategia propia permite precargar solo las rutas con más probabilidad de visitarse.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-05-S4', 'ANG-05', 'Senior', 'open', '¿Cómo organizarías la capa de acceso a la API en un proyecto grande?', 'How would you organize the API layer in a large project?', null, '{}'::text[], null, null, null, 'typed services per domain; DTOs vs domain models with mapping; generated clients from OpenAPI; interceptors for auth, errors, loading; environment config via injection token; caching strategy; error handling consistent; tests with HttpTestingController', 'I''d create typed services per domain, ideally generated from the backend''s OpenAPI spec so the contracts stay in sync. I''d map the API DTOs to the models the UI needs, so backend changes don''t spread everywhere. Cross-cutting concerns like auth, errors and retries go in interceptors, and the base URL comes from an injection token per environment. And I''d test the services with HttpTestingController.', 'Crearía servicios tipados por dominio, idealmente generados a partir de la especificación OpenAPI del backend, para que los contratos estén siempre sincronizados. Transformaría los DTO de la API en los modelos que necesita la interfaz, para que los cambios del backend no se propaguen por todas partes. Lo transversal, como autenticación, errores y reintentos, iría en interceptores, y la URL base vendría de un injection token por entorno. Y testearía los servicios con HttpTestingController.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-J1', 'ANG-06', 'Junior', 'mc', '¿Qué hace `fixture.detectChanges()`?', null, 'Ejecuta la detección de cambios para que la plantilla refleje el estado (y la primera vez dispara ngOnInit)', array['Reinicia el TestBed', 'Mockea los servicios', 'Compila los estilos']::text[], 'En los tests no hay detección automática: si no lo llamas, el DOM no cambia.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-J2', 'ANG-06', 'Junior', 'mc', '¿Qué es un test unitario?', null, 'Un test que comprueba una pieza aislada (un servicio, un componente) sin dependencias reales', array['Un test que abre la app en un navegador real', 'Una prueba manual', 'Un test de carga']::text[], 'Los E2E prueban la app completa como un usuario; los unitarios, una pieza aislada.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-J3', 'ANG-06', 'Junior', 'fill', 'Para sustituir un servicio real por uno falso en TestBed se usa { provide: UserService, ___: fakeService }.', null, 'useValue', array['useReal', 'inject', 'mock']::text[], 'También existen useClass y useFactory.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-J4', 'ANG-06', 'Junior', 'open', '¿Por qué son importantes los tests en un proyecto frontend?', 'Why are tests important in a frontend project?', null, '{}'::text[], null, null, null, 'catch regressions; confidence to refactor; documentation of behaviour; faster feedback than manual testing; CI; better design', 'Tests catch regressions before users do, and they give you the confidence to refactor without breaking things. They also document how a component is supposed to behave. And when they run in the CI pipeline, the team gets fast feedback on every change, which is much cheaper than finding bugs manually later.', 'Los tests detectan regresiones antes que los usuarios y dan confianza para refactorizar sin romper nada. También documentan cómo debe comportarse un componente. Y cuando se ejecutan en el pipeline de CI, el equipo recibe feedback rápido en cada cambio, que es mucho más barato que encontrar los errores a mano más tarde.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-M1', 'ANG-06', 'Mid', 'mc', '¿Cómo testeas llamadas HTTP sin backend real?', null, 'provideHttpClientTesting() y HttpTestingController (expectOne, flush, verify)', array['Con una API real de pruebas', 'Con setTimeout', 'Con RouterTestingModule']::text[], 'verify() asegura que no quedan peticiones sin responder.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-M2', 'ANG-06', 'Mid', 'mc', '¿Para qué sirven `fakeAsync` y `tick()`?', null, 'Para simular el paso del tiempo (timers, debounceTime) de forma síncrona', array['Para ejecutar tests en paralelo', 'Para medir la red', 'Para saltarse tests']::text[], 'tick(300) adelanta el reloj virtual 300 ms.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-M3', 'ANG-06', 'Mid', 'mc', '¿Qué es mejor comprobar en un test de componente?', null, 'Lo que ve y hace el usuario (texto, botones, eventos), no los detalles internos', array['Que se llamen todos los métodos privados', 'El número de líneas del componente', 'Los estilos CSS exactos']::text[], 'Los tests centrados en comportamiento sobreviven a los refactors.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-M4', 'ANG-06', 'Mid', 'open', '¿Cómo testearías un componente que carga usuarios desde un servicio y los muestra?', 'How would you test a component that loads users from a service and displays them?', null, '{}'::text[], null, null, null, 'TestBed; fake service with useValue returning of([...]); detectChanges; query DOM and assert items; empty, loading and error states (throwError)', 'I''d configure TestBed with the component and a fake UserService provided with useValue, returning of() with two users. I call detectChanges, query the list items and check there are two with the right names. Then separate tests for the empty state and for an error, making the fake return throwError and checking the error message is shown.', 'Configuraría TestBed con el componente y un UserService falso con useValue que devuelva of() con dos usuarios. Llamo a detectChanges, busco los elementos de la lista y compruebo que hay dos con los nombres correctos. Después haría tests aparte para el estado vacío y para un error, haciendo que el servicio falso devuelva throwError y comprobando que aparece el mensaje de error.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-S1', 'ANG-06', 'Senior', 'mc', '¿Qué describe la pirámide de tests?', null, 'Muchos tests unitarios, menos de integración y pocos E2E, por coste y velocidad', array['Muchos E2E y pocos unitarios', 'Solo tests manuales', 'Un test por archivo']::text[], 'Los E2E son caros y lentos; se reservan para los flujos críticos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-S2', 'ANG-06', 'Senior', 'mc', 'Un test E2E falla de vez en cuando sin cambios en el código (flaky). ¿Qué haces?', null, 'Investigar la causa (esperas fijas, datos compartidos, dependencias externas) y corregirla; aislarlo mientras tanto', array['Añadir reintentos infinitos', 'Borrarlo', 'Ignorar el pipeline']::text[], 'Los tests flaky destruyen la confianza en la suite. Esperar a condiciones, no a tiempos fijos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-S3', 'ANG-06', 'Senior', 'mc', '¿Qué es cierto sobre la cobertura de código?', null, 'Es una señal útil pero no garantiza calidad: puedes tener 90% sin comprobar nada importante', array['100% de cobertura significa cero bugs', 'No sirve para nada', 'Solo se mide en E2E']::text[], 'Mejor fijar mínimos razonables y revisar qué se prueba, no solo cuánto.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('ANG-06-S4', 'ANG-06', 'Senior', 'open', '¿Cómo definirías la estrategia de testing de un equipo frontend?', 'How would you define the testing strategy for a frontend team?', null, '{}'::text[], null, null, null, 'test pyramid; unit for logic and components; integration for features; few E2E for critical flows (Playwright/Cypress); runner choice (Vitest/Jest/Karma); CI gates; coverage as guide; testing behaviour not implementation; fixtures/mocks; code review', 'I''d follow the test pyramid: unit tests for services and components focused on behaviour, some integration tests for full features, and a small set of E2E tests with Playwright or Cypress for the critical flows like login or checkout. All of them run in CI and block merges when they fail. Coverage is a guide, not a goal. And tests are part of code review, so the whole team owns them.', 'Seguiría la pirámide de tests: tests unitarios de servicios y componentes centrados en el comportamiento, algunos tests de integración de funcionalidades completas y un conjunto pequeño de E2E con Playwright o Cypress para los flujos críticos, como el login o el pago. Todos se ejecutan en CI y bloquean el merge si fallan. La cobertura es una guía, no un objetivo. Y los tests forman parte de la code review, para que todo el equipo se responsabilice de ellos.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-J1', 'REA-01', 'Junior', 'mc', '¿Qué es JSX?', null, 'Una sintaxis parecida a HTML que se compila a llamadas de JavaScript para crear elementos', array['Un lenguaje distinto de JavaScript que el navegador entiende directamente', 'Un motor de plantillas del servidor', 'Un framework CSS']::text[], 'El navegador no entiende JSX: un compilador (Babel, SWC, esbuild) lo transforma.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-J2', 'REA-01', 'Junior', 'mc', '¿Diferencia entre props y estado?', null, 'Las props llegan del padre y son de solo lectura; el estado es interno y el componente lo cambia', array['Son lo mismo', 'El estado llega del padre', 'Las props solo pueden ser strings']::text[], 'Si cambia el estado o llegan props nuevas, el componente se vuelve a renderizar.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-J3', 'REA-01', 'Junior', 'fill', 'Al pintar una lista con map(), cada elemento necesita una prop ___ única y estable.', null, 'key', array['id', 'ref', 'index']::text[], 'Usar el índice como key da problemas si la lista se reordena o se filtra.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-J4', 'REA-01', 'Junior', 'open', '¿Qué es un componente en React?', 'What is a component in React?', null, '{}'::text[], null, null, null, 'reusable piece of UI; function that receives props and returns JSX; can have state with hooks; composition', 'A component is a reusable piece of the user interface. In modern React it''s just a function that receives props and returns JSX describing what to show. It can have its own state with hooks like useState, and you build the app by composing small components into bigger ones.', 'Un componente es una pieza reutilizable de la interfaz. En React moderno es simplemente una función que recibe props y devuelve JSX describiendo lo que hay que mostrar. Puede tener su propio estado con hooks como useState, y la aplicación se construye combinando componentes pequeños en otros más grandes.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-M1', 'REA-01', 'Mid', 'mc', '¿Por qué no se debe mutar el estado directamente (p. ej. `items.push(x)`)?', null, 'React compara referencias: si mutas, la referencia no cambia y puede no volver a renderizar', array['Porque push no existe en React', 'Porque el estado es una constante de TypeScript', 'No hay ningún problema']::text[], 'Crea copias: setItems([...items, x]).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-M2', 'REA-01', 'Mid', 'mc', '¿Qué es un componente controlado en un formulario?', null, 'Un input cuyo valor viene del estado de React y se actualiza con onChange', array['Un input que gestiona el DOM por su cuenta', 'Un componente con PropTypes', 'Un componente sin props']::text[], 'El no controlado guarda el valor en el DOM y se lee con una ref.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-M3', 'REA-01', 'Mid', 'mc', '¿Qué es el ''lifting state up''?', null, 'Subir el estado al ancestro común cuando varios componentes lo necesitan', array['Guardar el estado en localStorage', 'Usar Redux siempre', 'Pasar el estado a un hijo']::text[], 'El padre guarda el estado y lo pasa por props, junto con funciones para cambiarlo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-M4', 'REA-01', 'Mid', 'open', '¿Qué pasa cuando cambia el estado de un componente?', 'What happens when a component''s state changes?', null, '{}'::text[], null, null, null, 'React schedules a re-render; component function runs again; new virtual tree compared with previous (reconciliation); minimal DOM updates; children re-render too unless memoized; batching', 'When state changes, React schedules a re-render: it calls the component function again and gets a new description of the UI. Then it compares it with the previous one, which is called reconciliation, and only updates the parts of the DOM that actually changed. By default the children re-render too, and several state updates in the same event are batched together.', 'Cuando cambia el estado, React programa un nuevo renderizado: vuelve a llamar a la función del componente y obtiene una nueva descripción de la interfaz. Después la compara con la anterior, lo que se llama reconciliación, y solo actualiza en el DOM lo que ha cambiado de verdad. Por defecto también se vuelven a renderizar los hijos, y varias actualizaciones de estado en el mismo evento se agrupan.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-S1', 'REA-01', 'Senior', 'mc', '¿Qué es la reconciliación?', null, 'El proceso por el que React compara el árbol anterior con el nuevo y decide qué cambiar en el DOM', array['Un patrón de Redux', 'La fusión de ramas en Git', 'La hidratación del servidor']::text[], 'Las keys y el tipo de elemento guían ese algoritmo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-S2', 'REA-01', 'Senior', 'mc', '¿Qué ventaja tiene la composición (children, props de render) frente a la herencia en React?', null, 'Componentes más flexibles y reutilizables sin jerarquías rígidas', array['Mejor rendimiento siempre', 'Es obligatoria en TypeScript', 'Ninguna']::text[], 'React recomienda composición; la herencia entre componentes casi nunca se usa.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-S3', 'REA-01', 'Senior', 'mc', '¿Qué aportan los Server Components (p. ej. en Next.js)?', null, 'Se renderizan en el servidor, pueden acceder a datos directamente y no envían su JavaScript al cliente', array['Sustituyen a los hooks en el cliente', 'Funcionan sin servidor', 'Solo sirven para CSS']::text[], 'Los componentes interactivos siguen siendo de cliente (''use client'').', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-01-S4', 'REA-01', 'Senior', 'open', '¿Cómo estructurarías una aplicación React grande?', 'How would you structure a large React application?', null, '{}'::text[], null, null, null, 'feature-based folders; shared UI/design system; separation of server state and UI state; routing; data layer; TypeScript; linting and testing; conventions documented; avoid premature abstraction', 'I''d organize it by features instead of by file type, with a shared design system for common UI. I''d separate server state, handled with something like TanStack Query, from local UI state. TypeScript everywhere, a clear routing structure, and a data layer that hides the API details. Plus linting, tests and written conventions, so the codebase stays consistent as the team grows.', 'La organizaría por funcionalidades en lugar de por tipo de archivo, con un design system compartido para la interfaz común. Separaría el estado del servidor, gestionado con algo como TanStack Query, del estado local de la interfaz. TypeScript en todo el proyecto, una estructura de rutas clara y una capa de datos que oculte los detalles de la API. Además, linting, tests y convenciones por escrito, para que el código siga siendo coherente a medida que crece el equipo.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-J1', 'REA-02', 'Junior', 'mc', '¿Qué devuelve `useState`?', null, 'Un array con el valor actual y una función para cambiarlo', array['Solo el valor', 'Una promesa', 'Un objeto con get y set']::text[], 'const [count, setCount] = useState(0).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-J2', 'REA-02', 'Junior', 'mc', '¿Cuándo se ejecuta `useEffect(() => {...}, [])`?', null, 'Una vez tras el primer render (y su limpieza al desmontar)', array['En cada render', 'Antes del primer render', 'Nunca']::text[], 'En desarrollo con StrictMode se ejecuta dos veces a propósito para detectar efectos mal limpiados.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-J3', 'REA-02', 'Junior', 'fill', 'Los hooks solo se pueden llamar en el nivel superior de un componente, nunca dentro de ___.', null, 'condiciones o bucles', array['funciones flecha', 'archivos .tsx', 'componentes']::text[], 'React identifica cada hook por su orden de llamada; si cambia el orden, se rompe.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-J4', 'REA-02', 'Junior', 'open', '¿Qué son los hooks?', 'What are hooks?', null, '{}'::text[], null, null, null, 'functions that let function components use state and other React features; useState, useEffect, useContext; rules of hooks; custom hooks to reuse logic', 'Hooks are functions that let function components use React features like state and side effects. The most common are useState, useEffect and useContext. They have two rules: call them at the top level, and only from components or other hooks. You can also write custom hooks to reuse logic between components.', 'Los hooks son funciones que permiten a los componentes de función usar características de React como el estado o los efectos secundarios. Los más comunes son useState, useEffect y useContext. Tienen dos reglas: llamarlos siempre en el nivel superior y solo desde componentes u otros hooks. También puedes crear hooks propios para reutilizar lógica entre componentes.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-M1', 'REA-02', 'Mid', 'mc', '¿Para qué sirve la función de limpieza de useEffect?', null, 'Para deshacer lo que hizo el efecto (desuscribirse, cancelar timers o peticiones) antes del siguiente efecto o al desmontar', array['Para limpiar el estado', 'Para borrar el DOM', 'Para reiniciar el componente']::text[], 'Sin limpieza aparecen fugas y actualizaciones de estado en componentes desmontados.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-M2', 'REA-02', 'Mid', 'mc', '¿Diferencia entre `useMemo` y `useCallback`?', null, 'useMemo memoriza un valor calculado; useCallback memoriza una función', array['Son lo mismo', 'useCallback memoriza valores y useMemo funciones', 'Solo funcionan en clases']::text[], 'useCallback(fn, deps) equivale a useMemo(() => fn, deps).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-M3', 'REA-02', 'Mid', 'mc', '¿Para qué se usa `useRef`?', null, 'Guardar un valor que persiste entre renders sin provocar re-render, o referenciar un elemento del DOM', array['Para el estado global', 'Para hacer peticiones', 'Para memorizar funciones']::text[], 'Cambiar ref.current no vuelve a renderizar.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-M4', 'REA-02', 'Mid', 'open', '¿Cómo harías un custom hook para pedir datos a una API?', 'How would you write a custom hook to fetch data from an API?', null, '{}'::text[], null, null, null, 'useState for data, loading, error; useEffect depending on url; AbortController to cancel; cleanup; return object; mention TanStack Query for real apps (caching, retries)', 'I''d create a useFetch hook with state for data, loading and error. Inside a useEffect that depends on the URL, I''d start the request with an AbortController and cancel it in the cleanup, so we don''t update state after unmount or with stale responses. It returns data, loading and error. In a real project, though, I''d probably use TanStack Query, because it adds caching, retries and refetching for free.', 'Crearía un hook useFetch con estado para los datos, la carga y el error. Dentro de un useEffect que depende de la URL, lanzaría la petición con un AbortController y la cancelaría en la función de limpieza, para no actualizar el estado tras desmontar el componente ni con respuestas antiguas. Devuelve data, loading y error. Aunque en un proyecto real seguramente usaría TanStack Query, porque ya trae caché, reintentos y recarga de datos.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-S1', 'REA-02', 'Senior', 'mc', 'Un useEffect se ejecuta en bucle infinito. ¿Causa más probable?', null, 'Una dependencia que se recrea en cada render (objeto, array o función) o un setState que cambia una dependencia', array['React está mal instalado', 'Falta un key', 'El componente es demasiado grande']::text[], 'Soluciones: memorizar la dependencia, mover el objeto fuera o replantear si el efecto es necesario.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-S2', 'REA-02', 'Senior', 'mc', '¿Qué dice la guía ''You might not need an effect''?', null, 'Muchos efectos sobran: los valores derivados se calculan en el render y las acciones del usuario van en los manejadores de eventos', array['Hay que usar efectos para todo', 'Los efectos están obsoletos', 'Solo se usan efectos en clases']::text[], 'Los efectos son para sincronizar con sistemas externos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-S3', 'REA-02', 'Senior', 'mc', '¿Qué hace `useTransition`?', null, 'Marca una actualización como no urgente para que la UI siga respondiendo mientras se procesa', array['Anima transiciones CSS', 'Cambia de ruta', 'Retrasa el useEffect']::text[], 'Útil, por ejemplo, para filtrar una lista enorme sin bloquear el input.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-02-S4', 'REA-02', 'Senior', 'open', '¿Cuándo crees que se abusa de useMemo y useCallback?', 'When do you think useMemo and useCallback are overused?', null, '{}'::text[], null, null, null, 'memoization has a cost; only useful when computation is expensive or referential equality matters (memo children, effect deps); measure with Profiler; React Compiler can automate it', 'They''re overused when people wrap everything by default. Memoization has its own cost and makes code harder to read. They make sense when a calculation is really expensive, or when you need a stable reference, for example for a child wrapped in memo or a dependency of an effect. I''d measure with the React Profiler first, and with the React Compiler a lot of this can be automatic anyway.', 'Se abusa de ellos cuando se envuelve todo por defecto. Memorizar tiene su propio coste y hace el código más difícil de leer. Tienen sentido cuando un cálculo es realmente costoso o cuando necesitas una referencia estable, por ejemplo para un hijo envuelto en memo o una dependencia de un efecto. Primero mediría con el Profiler de React, y con el React Compiler buena parte de esto se hace sola.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-J1', 'REA-03', 'Junior', 'mc', '¿Qué problema resuelve Context?', null, 'Pasar datos a muchos componentes sin ir prop por prop por toda la jerarquía (prop drilling)', array['Hacer peticiones HTTP', 'Mejorar el rendimiento siempre', 'Sustituir a useState']::text[], 'Se usa para datos como el tema, el idioma o el usuario logueado.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-J2', 'REA-03', 'Junior', 'fill', 'Para leer un contexto dentro de un componente se usa el hook ___.', null, 'useContext', array['useState', 'useProvider', 'useStore']::text[], 'El valor viene del Provider más cercano en el árbol.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-J3', 'REA-03', 'Junior', 'mc', '¿Dónde es mejor hacer una petición inicial de datos en un componente de cliente sencillo?', null, 'En un useEffect (o mejor, con una librería como TanStack Query)', array['Directamente en el cuerpo del componente', 'En el constructor', 'En el CSS']::text[], 'Hacerla en el cuerpo la lanzaría en cada render.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-J4', 'REA-03', 'Junior', 'open', '¿Qué es el prop drilling y cómo lo evitas?', 'What is prop drilling and how do you avoid it?', null, '{}'::text[], null, null, null, 'passing props through many layers that don''t use them; solutions: component composition, Context, state management library; keep state close', 'Prop drilling is when you pass a prop through many components that don''t need it, just to reach a deep child. To avoid it, I first try composition, passing components as children. If the data is really global, like the user or the theme, I use Context. And for complex shared state, a library like Zustand or Redux Toolkit.', 'El prop drilling es pasar una prop por muchos componentes que no la necesitan solo para que llegue a un hijo profundo. Para evitarlo, primero pruebo con composición, pasando componentes como children. Si el dato es realmente global, como el usuario o el tema, uso Context. Y para un estado compartido complejo, una librería como Zustand o Redux Toolkit.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-M1', 'REA-03', 'Mid', 'mc', '¿Qué aporta TanStack Query (React Query)?', null, 'Gestión del estado del servidor: caché, reintentos, refetch, estados de carga y error', array['Un sistema de routing', 'Un framework CSS', 'Sustituye a useState para todo']::text[], 'Separa el estado del servidor del estado de la UI.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-M2', 'REA-03', 'Mid', 'mc', 'Un problema de rendimiento típico de Context es…', null, 'Todos los consumidores se vuelven a renderizar cuando cambia el valor, aunque solo usen una parte', array['No funciona con TypeScript', 'Solo admite strings', 'No se puede anidar']::text[], 'Se mitiga dividiendo contextos o memorizando el valor.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-M3', 'REA-03', 'Mid', 'mc', 'Redux Toolkit frente al Redux clásico:', null, 'Reduce el código repetitivo con createSlice y usa Immer para escribir actualizaciones inmutables de forma sencilla', array['Elimina la store', 'Ya no usa acciones', 'Solo funciona con clases']::text[], 'Es la forma recomendada de usar Redux hoy.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-M4', 'REA-03', 'Mid', 'open', '¿Qué tipos de estado hay en una app React y dónde guardarías cada uno?', 'What kinds of state are there in a React app and where would you keep each one?', null, '{}'::text[], null, null, null, 'local UI state (useState); shared client state (Context, Zustand, Redux); server state (TanStack Query); URL state (router params/search); form state (form library)', 'I separate it into four kinds. Local UI state, like whether a modal is open, stays in useState. Shared client state, like the logged-in user, goes in Context or a small store like Zustand. Server data goes in TanStack Query, which handles caching and refetching. And things like filters or the current page belong in the URL, so they survive a refresh and can be shared.', 'Lo separo en cuatro tipos. El estado local de interfaz, como si un modal está abierto, se queda en useState. El estado compartido del cliente, como el usuario que ha iniciado sesión, va en Context o en una store pequeña como Zustand. Los datos del servidor van en TanStack Query, que gestiona la caché y la recarga. Y cosas como los filtros o la página actual pertenecen a la URL, para que sobrevivan a una recarga y se puedan compartir.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-S1', 'REA-03', 'Senior', 'mc', '¿Qué es una actualización optimista?', null, 'Actualizar la UI antes de que responda el servidor y revertir si la petición falla', array['Esperar siempre al servidor', 'Cachear para siempre', 'Hacer dos peticiones']::text[], 'Mejora la sensación de velocidad; TanStack Query y useOptimistic lo facilitan.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-S2', 'REA-03', 'Senior', 'mc', '¿Cuándo elegirías Redux Toolkit frente a Zustand?', null, 'Redux si necesitas convenciones estrictas, middleware y devtools en un equipo grande; Zustand si buscas algo mínimo y sencillo', array['Zustand siempre es mejor', 'Redux siempre es mejor', 'Son incompatibles con TypeScript']::text[], 'No hay una respuesta única: depende del tamaño del equipo y la complejidad.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-S3', 'REA-03', 'Senior', 'mc', '¿Cómo evitas mostrar datos antiguos tras una mutación?', null, 'Invalidando las queries afectadas o actualizando la caché con la respuesta', array['Recargando la página', 'Desactivando la caché', 'Usando setTimeout']::text[], 'queryClient.invalidateQueries o setQueryData.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-03-S4', 'REA-03', 'Senior', 'open', '¿Cómo diseñarías la capa de datos de una app con muchas pantallas que comparten información?', 'How would you design the data layer of an app with many screens sharing data?', null, '{}'::text[], null, null, null, 'server state library with caching and query keys; typed API client (OpenAPI); normalized or keyed cache; invalidation strategy; optimistic updates; error/loading conventions; avoid duplicating server data in global store', 'I''d use a server state library like TanStack Query as the single source for API data, with consistent query keys, so screens share the cache instead of refetching. A typed API client, ideally generated from OpenAPI. Clear rules for invalidation after mutations, optimistic updates where it helps, and shared components for loading and error states. And I''d avoid copying server data into a global store, because that creates two sources of truth.', 'Usaría una librería de estado del servidor como TanStack Query como única fuente de los datos de la API, con claves de consulta coherentes para que las pantallas compartan la caché en lugar de volver a pedir los datos. Un cliente de API tipado, idealmente generado desde OpenAPI. Reglas claras de invalidación tras cada mutación, actualizaciones optimistas donde aporten y componentes comunes para los estados de carga y error. Y evitaría copiar datos del servidor en una store global, porque crea dos fuentes de verdad.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-J1', 'REA-04', 'Junior', 'mc', '¿Qué hace `React.memo`?', null, 'Evita volver a renderizar un componente si sus props no han cambiado', array['Guarda datos en localStorage', 'Memoriza peticiones HTTP', 'Hace el componente asíncrono']::text[], 'Compara las props de forma superficial.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-J2', 'REA-04', 'Junior', 'mc', '¿Qué herramienta usarías para ver qué componentes se renderizan y cuánto tardan?', null, 'El Profiler de React DevTools', array['La consola de Node', 'npm audit', 'Git']::text[], 'Permite ver cada commit de render y su coste.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-J3', 'REA-04', 'Junior', 'fill', 'Cargar un componente solo cuando se necesita se hace con React.___ y Suspense.', null, 'lazy', array['memo', 'use', 'defer']::text[], 'const Admin = React.lazy(() => import(''./Admin'')).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-J4', 'REA-04', 'Junior', 'open', '¿Qué harías si una página de React va lenta?', 'What would you do if a React page is slow?', null, '{}'::text[], null, null, null, 'measure with React DevTools Profiler and browser tools; find unnecessary re-renders or heavy computations; memo/useMemo; virtualize long lists; code splitting; measure again', 'First I''d measure with the React Profiler and the browser''s performance tools, to find out if the problem is unnecessary re-renders, a heavy calculation or a big bundle. Then I''d apply the right fix: memo for components that re-render for no reason, useMemo for expensive calculations, virtualization for long lists, or lazy loading for big pages. And I''d measure again to confirm it helped.', 'Primero mediría con el Profiler de React y las herramientas de rendimiento del navegador, para saber si el problema son renderizados innecesarios, un cálculo pesado o un bundle grande. Después aplicaría la solución adecuada: memo para componentes que se renderizan sin motivo, useMemo para cálculos costosos, virtualización para listas largas o carga diferida para páginas grandes. Y volvería a medir para confirmar la mejora.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-M1', 'REA-04', 'Mid', 'mc', 'Pasas una función nueva como prop a un hijo con React.memo en cada render. ¿Qué ocurre?', null, 'El hijo se vuelve a renderizar igualmente, porque la referencia de la función cambia', array['No pasa nada', 'React lanza un error', 'El hijo deja de renderizar']::text[], 'useCallback mantiene la misma referencia entre renders.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-M2', 'REA-04', 'Mid', 'mc', 'Para listas de miles de elementos, lo más efectivo es…', null, 'Virtualizar (react-window, TanStack Virtual)', array['Usar más keys', 'Añadir más useEffect', 'Pasar a clases']::text[], 'Solo se pinta lo visible.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-M3', 'REA-04', 'Mid', 'mc', '¿Qué mide el INP (Interaction to Next Paint)?', null, 'Cuánto tarda la página en responder visualmente a las interacciones del usuario', array['El tiempo de descarga del HTML', 'El tamaño del bundle', 'La memoria usada']::text[], 'Es una de las Core Web Vitals, junto a LCP y CLS.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-M4', 'REA-04', 'Mid', 'open', '¿Qué es el code splitting y cómo lo aplicarías?', 'What is code splitting and how would you apply it?', null, '{}'::text[], null, null, null, 'split bundle into chunks loaded on demand; route-based splitting with lazy + Suspense; heavy components/libraries loaded lazily; dynamic import; analyze bundle', 'Code splitting means breaking the JavaScript bundle into smaller chunks that are loaded only when needed. The easiest win is splitting by route, using lazy and Suspense, so each page loads its own code. I''d also lazy load heavy components like charts or editors. And I''d use a bundle analyzer to find the biggest dependencies.', 'El code splitting consiste en dividir el bundle de JavaScript en trozos más pequeños que se cargan solo cuando hacen falta. Lo más fácil es dividir por rutas, con lazy y Suspense, para que cada página cargue su propio código. También cargaría de forma diferida componentes pesados como gráficos o editores. Y usaría un analizador de bundle para encontrar las dependencias más grandes.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-S1', 'REA-04', 'Senior', 'mc', '¿Qué hace el React Compiler?', null, 'Añade memorización automáticamente en tiempo de compilación, reduciendo la necesidad de useMemo/useCallback manuales', array['Convierte React a Vue', 'Elimina el virtual DOM', 'Compila a WebAssembly']::text[], 'Exige que el código siga las reglas de React (componentes puros, hooks bien usados).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-S2', 'REA-04', 'Senior', 'mc', '¿Qué aporta el streaming SSR con Suspense?', null, 'El servidor envía el HTML por partes y la página se muestra antes, sin esperar a los datos más lentos', array['Sustituye al CDN', 'Elimina el JavaScript', 'Solo sirve para vídeo']::text[], 'Las partes lentas muestran un fallback hasta que llegan.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-S3', 'REA-04', 'Senior', 'mc', '¿Por qué conviene medir en producción (RUM) además de en local?', null, 'Porque los usuarios reales tienen dispositivos y redes muy distintos a tu máquina', array['Porque en local no funciona el Profiler', 'No conviene', 'Por obligación legal']::text[], 'Los datos de campo (RUM) muestran lo que de verdad sufren los usuarios.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-04-S4', 'REA-04', 'Senior', 'open', '¿Cómo mejorarías el tiempo de carga inicial de una aplicación React grande?', 'How would you improve the initial load time of a large React application?', null, '{}'::text[], null, null, null, 'measure LCP/bundle; route and component code splitting; remove/replace heavy dependencies; tree shaking; SSR/SSG or streaming; image optimization; caching/CDN; preload critical resources; budgets in CI', 'I''d start by measuring LCP and analyzing the bundle. Then: split code by route, replace or lazy load heavy libraries, and make sure tree shaking works. If SEO or first paint matter, I''d consider server rendering or static generation with a framework like Next.js. Images optimized and served from a CDN, critical resources preloaded, and performance budgets in CI to avoid going backwards.', 'Empezaría midiendo el LCP y analizando el bundle. Después: dividir el código por rutas, sustituir o cargar de forma diferida las librerías pesadas y asegurarme de que el tree shaking funciona. Si importan el SEO y el primer pintado, consideraría el renderizado en servidor o la generación estática con un framework como Next.js. Imágenes optimizadas y servidas desde un CDN, recursos críticos precargados y presupuestos de rendimiento en CI para no ir hacia atrás.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-J1', 'REA-05', 'Junior', 'mc', '¿Qué librería se usa habitualmente para la navegación en una SPA de React?', null, 'React Router (o el router de un framework como Next.js)', array['Express', 'Axios', 'Jest']::text[], 'React no trae router propio.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-J2', 'REA-05', 'Junior', 'fill', 'En React Router, para navegar sin recargar la página se usa el componente ___.', null, '<Link>', array['<a>', '<Route>', '<Navigate>']::text[], 'Un <a> normal recargaría la página entera.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-J3', 'REA-05', 'Junior', 'mc', '¿Qué es una SPA?', null, 'Una aplicación de una sola página que cambia el contenido sin recargar el documento', array['Una web con un solo archivo HTML y sin JavaScript', 'Un servidor de APIs', 'Una app nativa']::text[], 'El routing ocurre en el cliente.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-J4', 'REA-05', 'Junior', 'open', '¿Diferencia entre React y Next.js?', 'What''s the difference between React and Next.js?', null, '{}'::text[], null, null, null, 'React is a UI library; Next.js is a framework on top: file-based routing, SSR/SSG, server components, API routes, optimizations', 'React is a library for building user interfaces, so you still need to choose a router, a build setup and so on. Next.js is a framework built on top of React that gives you file-based routing, server-side rendering and static generation, server components, API routes and lots of built-in optimizations. It''s a full solution for production apps.', 'React es una librería para construir interfaces, así que todavía tienes que elegir router, configuración de build, etc. Next.js es un framework construido sobre React que te da rutas basadas en archivos, renderizado en servidor y generación estática, server components, rutas de API y muchas optimizaciones integradas. Es una solución completa para aplicaciones en producción.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-M1', 'REA-05', 'Mid', 'mc', '¿Cómo proteges una ruta privada en React Router?', null, 'Con un componente o loader que comprueba la sesión y redirige con <Navigate> o redirect si no hay usuario', array['Ocultando el enlace en el menú', 'Con CSS', 'No se puede']::text[], 'Ocultar el enlace no basta: el usuario puede escribir la URL. Y la seguridad real está en el backend.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-M2', 'REA-05', 'Mid', 'mc', '¿Qué son los loaders de React Router (data routers)?', null, 'Funciones que cargan datos antes de renderizar la ruta', array['Spinners de carga', 'Componentes de error', 'Hooks de estado']::text[], 'Evitan cascadas de peticiones y simplifican los estados de carga.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-M3', 'REA-05', 'Mid', 'mc', '¿Dónde guardarías los filtros de una tabla para poder compartir el enlace?', null, 'En los query params de la URL', array['En useState', 'En una variable global', 'En sessionStorage']::text[], 'useSearchParams los lee y escribe.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-M4', 'REA-05', 'Mid', 'open', '¿Cómo organizarías las carpetas de un proyecto React mediano?', 'How would you organize the folders of a medium-sized React project?', null, '{}'::text[], null, null, null, 'feature-based folders (components, hooks, api, tests together); shared components/ui; lib/utils; routes/pages; consistent naming; avoid deep nesting; colocation', 'I''d group by feature: each feature folder contains its components, hooks, API calls and tests together, so related code lives side by side. Then a shared folder for the UI kit and common hooks, a lib folder for utilities and the API client, and a routes or pages folder. The key is colocation and consistent naming, without too many nested levels.', 'Agruparía por funcionalidades: cada carpeta contiene sus componentes, hooks, llamadas a la API y tests, de modo que el código relacionado está junto. Después, una carpeta compartida para el kit de UI y los hooks comunes, una carpeta lib para utilidades y el cliente de la API, y una carpeta de rutas o páginas. La clave es tener junto lo que va junto y nombrar de forma coherente, sin demasiados niveles de anidación.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-S1', 'REA-05', 'Senior', 'mc', '¿Qué diferencia hay entre SSR, SSG e ISR?', null, 'SSR genera el HTML en cada petición; SSG en el build; ISR regenera páginas estáticas cada cierto tiempo o bajo demanda', array['Son sinónimos', 'SSG es solo para APIs', 'ISR elimina el servidor']::text[], 'Se elige según lo dinámicos que sean los datos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-S2', 'REA-05', 'Senior', 'mc', '¿Qué ventaja tiene un monorepo (Nx, Turborepo) para varios frontends?', null, 'Compartir código y configuración, cambios atómicos entre paquetes y builds incrementales', array['Despliegues más lentos', 'Elimina la necesidad de tests', 'Obliga a usar un solo framework']::text[], 'A cambio exige buenas herramientas y reglas de dependencias.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-S3', 'REA-05', 'Senior', 'mc', '¿Qué es un design system y por qué ayuda?', null, 'Un conjunto de componentes, tokens y reglas compartidas que hace la UI consistente y acelera el desarrollo', array['Un tipo de base de datos', 'Un framework de testing', 'Una librería de estado']::text[], 'Suele vivir en su propio paquete con Storybook y tests visuales.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-05-S4', 'REA-05', 'Senior', 'open', '¿Cómo elegirías entre una SPA pura y un framework con SSR como Next.js?', 'How would you choose between a pure SPA and an SSR framework like Next.js?', null, '{}'::text[], null, null, null, 'SEO and first load needs; public vs internal app; data freshness; infrastructure and cost; team experience; complexity; hybrid options', 'It depends on the product. For a public site where SEO and the first load matter, like an e-commerce or a blog, I''d go with Next.js and server rendering. For an internal dashboard behind a login, a SPA is simpler and cheaper to host. I''d also consider the team''s experience and the infrastructure. And many frameworks let you mix both approaches page by page.', 'Depende del producto. Para una web pública donde importan el SEO y la primera carga, como un e-commerce o un blog, iría con Next.js y renderizado en servidor. Para un panel interno detrás de un login, una SPA es más sencilla y más barata de alojar. También tendría en cuenta la experiencia del equipo y la infraestructura. Y muchos frameworks permiten combinar los dos enfoques página a página.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-J1', 'REA-06', 'Junior', 'mc', '¿Qué filosofía sigue React Testing Library?', null, 'Testear como lo usaría un usuario: buscar por texto o rol y simular interacciones', array['Testear el estado interno y los métodos privados', 'Hacer snapshots de todo', 'Testear solo el CSS']::text[], 'Cuanto más se parezca el test al uso real, más confianza da.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-J2', 'REA-06', 'Junior', 'fill', 'Para buscar un botón accesible por su rol se usa screen.___(''button'', { name: /guardar/i }).', null, 'getByRole', array['getByClass', 'querySelector', 'findByCss']::text[], 'getByRole es la consulta preferida porque además comprueba accesibilidad.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-J3', 'REA-06', 'Junior', 'mc', '¿Qué herramientas se usan habitualmente para tests unitarios en React?', null, 'Jest o Vitest con React Testing Library', array['Selenium y JUnit', 'Postman', 'Webpack']::text[], 'Para E2E: Playwright o Cypress.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-J4', 'REA-06', 'Junior', 'open', '¿Qué testearías en un componente de formulario de login?', 'What would you test in a login form component?', null, '{}'::text[], null, null, null, 'renders fields; validation messages; submit calls handler/API with values; disabled button while loading; error message on failure; accessible labels', 'I''d check that the email and password fields render with accessible labels, that validation messages appear when the fields are empty or invalid, and that submitting calls the login function with the right values. I''d also test that the button is disabled while loading, and that an error message appears if the login fails.', 'Comprobaría que los campos de email y contraseña se muestran con etiquetas accesibles, que aparecen los mensajes de validación cuando están vacíos o son incorrectos y que al enviar se llama a la función de login con los valores correctos. También probaría que el botón se desactiva mientras carga y que aparece un mensaje de error si el login falla.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-M1', 'REA-06', 'Mid', 'mc', '¿Diferencia entre getBy, queryBy y findBy?', null, 'getBy lanza error si no existe; queryBy devuelve null; findBy espera de forma asíncrona', array['Son iguales', 'findBy es síncrono', 'queryBy lanza error']::text[], 'queryBy sirve para comprobar que algo NO está; findBy para lo que aparece tras una petición.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-M2', 'REA-06', 'Mid', 'mc', '¿Cómo simulas las peticiones HTTP en los tests de forma realista?', null, 'Con MSW (Mock Service Worker), interceptando las peticiones de red', array['Llamando a la API real', 'Borrando fetch', 'Con setTimeout']::text[], 'MSW permite reutilizar los mismos mocks en tests y en desarrollo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-M3', 'REA-06', 'Mid', 'mc', '¿Por qué se prefiere `userEvent` frente a `fireEvent`?', null, 'Simula interacciones completas como un usuario real (foco, teclado, clics) en vez de disparar un único evento', array['Es más rápido', 'fireEvent está prohibido', 'No hay diferencia']::text[], 'Por ejemplo, userEvent.type escribe letra a letra disparando todos los eventos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-M4', 'REA-06', 'Mid', 'open', '¿Cómo testearías un custom hook?', 'How would you test a custom hook?', null, '{}'::text[], null, null, null, 'renderHook from Testing Library; act for updates; mock dependencies/network (MSW); test returned values over time; or test through a component that uses it', 'I''d use renderHook from Testing Library, which renders the hook inside a test component. Then I check the returned values, and wrap updates in act. If the hook fetches data, I mock the network with MSW and wait for the result with waitFor. Sometimes it''s even more meaningful to test it through a real component that uses it.', 'Usaría renderHook de Testing Library, que renderiza el hook dentro de un componente de prueba. Después compruebo los valores que devuelve y envuelvo las actualizaciones en act. Si el hook pide datos, simulo la red con MSW y espero el resultado con waitFor. A veces tiene más sentido probarlo a través de un componente real que lo use.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-S1', 'REA-06', 'Senior', 'mc', '¿Qué problema tienen los tests de snapshot grandes?', null, 'Se actualizan sin revisarlos y acaban sin detectar nada útil', array['Son demasiado lentos siempre', 'No funcionan con TypeScript', 'Ninguno']::text[], 'Mejor snapshots pequeños y concretos, o aserciones explícitas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-S2', 'REA-06', 'Senior', 'mc', '¿Qué son los tests de regresión visual?', null, 'Comparar capturas de pantalla de componentes entre versiones para detectar cambios visuales no deseados', array['Tests de rendimiento', 'Tests de accesibilidad', 'Tests de carga']::text[], 'Herramientas como Chromatic o Playwright lo automatizan.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-S3', 'REA-06', 'Senior', 'mc', '¿Qué es el ''testing trophy'' de Kent C. Dodds?', null, 'Una propuesta que da más peso a los tests de integración, con análisis estático en la base', array['Un premio de testing', 'Una herramienta de cobertura', 'Un tipo de E2E']::text[], 'Es una alternativa a la pirámide clásica pensada para frontend.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('REA-06-S4', 'REA-06', 'Senior', 'open', '¿Cómo asegurarías la calidad de un frontend React en un equipo de 10 personas?', 'How would you ensure the quality of a React frontend in a team of 10 people?', null, '{}'::text[], null, null, null, 'TypeScript strict and ESLint; automated tests at several levels; CI gates; code review guidelines; design system and Storybook; visual and accessibility tests; monitoring errors in production; shared conventions', 'I''d combine automation and team practices. Strict TypeScript and ESLint catch a lot of problems early. Tests at several levels, mainly integration tests with Testing Library and a few E2E for critical flows, all running in CI and blocking merges. A design system with Storybook, plus visual and accessibility checks. Clear code review guidelines. And error monitoring in production, so we learn from real issues.', 'Combinaría automatización y prácticas de equipo. TypeScript estricto y ESLint detectan muchos problemas pronto. Tests en varios niveles, sobre todo de integración con Testing Library y unos pocos E2E para los flujos críticos, todos en CI y bloqueando el merge. Un design system con Storybook, más pruebas visuales y de accesibilidad. Pautas claras de code review. Y monitorización de errores en producción, para aprender de los problemas reales.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-J1', 'CLD-01', 'Junior', 'mc', '¿Qué es una Availability Zone?', null, 'Uno o varios centros de datos aislados dentro de una región', array['Un país donde AWS tiene clientes', 'Un tipo de instancia EC2', 'Una cuenta de AWS']::text[], 'Una región tiene varias AZ. Repartir recursos entre AZ da alta disponibilidad.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-J2', 'CLD-01', 'Junior', 'mc', '¿Qué servicio usarías para guardar archivos como imágenes o backups?', null, 'Amazon S3', array['Amazon EC2', 'Amazon RDS', 'AWS Lambda']::text[], 'S3 es almacenamiento de objetos, muy duradero y barato.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-J3', 'CLD-01', 'Junior', 'fill', 'En IAM, el principio de mínimo ___ dice que cada identidad debe tener solo los permisos que necesita.', null, 'privilegio', array['coste', 'acceso root', 'riesgo']::text[], 'Nunca uses la cuenta root para el día a día.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-J4', 'CLD-01', 'Junior', 'open', '¿Qué es el cloud computing y qué ventajas tiene frente a servidores propios?', 'What is cloud computing and what are its advantages over your own servers?', null, '{}'::text[], null, null, null, 'on-demand resources over the internet; pay as you go; scalability/elasticity; no upfront hardware; global reach; managed services; shared responsibility', 'Cloud computing means using computing resources, like servers, storage or databases, on demand over the internet and paying only for what you use. Compared to your own servers, you don''t buy hardware upfront, you can scale up or down in minutes, you can deploy close to users anywhere in the world, and you can use managed services so you spend less time on maintenance.', 'El cloud computing es usar recursos informáticos, como servidores, almacenamiento o bases de datos, bajo demanda a través de internet y pagando solo por lo que usas. Frente a tener tus propios servidores, no compras hardware por adelantado, puedes escalar en minutos, puedes desplegar cerca de los usuarios en cualquier parte del mundo y puedes usar servicios gestionados para dedicar menos tiempo al mantenimiento.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-M1', 'CLD-01', 'Mid', 'mc', '¿Diferencia entre un rol de IAM y un usuario de IAM?', null, 'El rol se asume temporalmente y da credenciales temporales; el usuario tiene credenciales permanentes', array['Son lo mismo', 'Los roles solo son para personas', 'Los usuarios no pueden tener políticas']::text[], 'Para servicios (EC2, Lambda) se usan siempre roles, nunca claves guardadas en el código.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-M2', 'CLD-01', 'Mid', 'mc', '¿Qué clase de S3 elegirías para backups que casi nunca se consultan?', null, 'S3 Glacier (Flexible Retrieval o Deep Archive)', array['S3 Standard', 'S3 Express One Zone', 'EBS']::text[], 'Las clases de archivo son mucho más baratas, a cambio de tiempos de recuperación largos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-M3', 'CLD-01', 'Mid', 'mc', '¿Qué es el modelo de responsabilidad compartida?', null, 'AWS se encarga de la seguridad DE la nube (hardware, infraestructura); el cliente, de la seguridad EN la nube (datos, configuración, accesos)', array['AWS se encarga de todo', 'El cliente se encarga de todo', 'Solo aplica a EC2']::text[], 'Cuanto más gestionado es el servicio, más responsabilidad asume AWS.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-M4', 'CLD-01', 'Mid', 'open', '¿Cuándo usarías EC2, Lambda o un contenedor en ECS/Fargate?', 'When would you use EC2, Lambda or a container on ECS/Fargate?', null, '{}'::text[], null, null, null, 'EC2: full control, long-running, special OS needs; Lambda: event-driven, short tasks, scale to zero, pay per use, limits (15 min); containers: portable apps, microservices, long-running without managing servers with Fargate', 'I''d use Lambda for event-driven, short tasks, like processing a file when it''s uploaded to S3, because it scales automatically and you pay only when it runs, but it has a time limit of fifteen minutes. For long-running services or microservices, I''d use containers on ECS with Fargate, so I don''t manage servers. And EC2 when I need full control of the operating system or special software.', 'Usaría Lambda para tareas cortas y basadas en eventos, como procesar un archivo cuando se sube a S3, porque escala sola y solo pagas cuando se ejecuta, aunque tiene un límite de quince minutos. Para servicios de larga duración o microservicios, usaría contenedores en ECS con Fargate, para no gestionar servidores. Y EC2 cuando necesito control total del sistema operativo o software especial.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-S1', 'CLD-01', 'Senior', 'mc', '¿Para qué sirve AWS Organizations con Service Control Policies?', null, 'Para gestionar muchas cuentas de forma centralizada y limitar lo que se puede hacer en cada una', array['Para facturar a clientes', 'Para crear VPCs', 'Para monitorizar logs']::text[], 'Una estrategia multicuenta (por entorno o equipo) aísla riesgos y costes.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-S2', 'CLD-01', 'Senior', 'mc', '¿Qué estrategia ayuda más a reducir costes en cargas estables y predecibles?', null, 'Savings Plans o instancias reservadas', array['Instancias Spot para todo', 'Subir el tamaño de las instancias', 'Desactivar el autoscaling']::text[], 'Spot es ideal para cargas tolerantes a interrupciones, no para todo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-S3', 'CLD-01', 'Senior', 'mc', '¿Qué son los pilares del Well-Architected Framework?', null, 'Excelencia operativa, seguridad, fiabilidad, eficiencia de rendimiento, optimización de costes y sostenibilidad', array['Velocidad, precio y diseño', 'Solo seguridad y coste', 'EC2, S3, RDS y Lambda']::text[], 'Son la base para revisar cualquier arquitectura en AWS.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-01-S4', 'CLD-01', 'Senior', 'open', '¿Cómo diseñarías una estrategia multicuenta en AWS para una empresa?', 'How would you design a multi-account strategy in AWS for a company?', null, '{}'::text[], null, null, null, 'AWS Organizations; separate accounts per environment/team/workload; OUs; SCP guardrails; centralized logging and security accounts; IAM Identity Center for SSO; Control Tower landing zone; consolidated billing; tagging', 'I''d use AWS Organizations with a landing zone, for example with Control Tower. Separate accounts for production, staging and development, grouped in organizational units, plus dedicated accounts for security and centralized logging. Service Control Policies as guardrails, IAM Identity Center for single sign-on, consolidated billing and a tagging policy, so we can track costs per team.', 'Usaría AWS Organizations con una landing zone, por ejemplo con Control Tower. Cuentas separadas para producción, preproducción y desarrollo, agrupadas en unidades organizativas, y cuentas dedicadas para seguridad y logs centralizados. Service Control Policies como barreras, IAM Identity Center para el inicio de sesión único, facturación consolidada y una política de etiquetado para seguir los costes por equipo.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-J1', 'CLD-02', 'Junior', 'mc', '¿Qué es una VPC?', null, 'Una red privada virtual y aislada dentro de AWS donde despliegas tus recursos', array['Un tipo de base de datos', 'Una VPN para empleados', 'Un balanceador']::text[], 'Dentro creas subredes, tablas de rutas y reglas de seguridad.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-J2', 'CLD-02', 'Junior', 'mc', '¿Qué diferencia una subred pública de una privada?', null, 'La pública tiene ruta a un Internet Gateway; la privada no tiene acceso directo desde internet', array['La pública es más barata', 'La privada no puede tener instancias', 'No hay diferencia']::text[], 'Las bases de datos y backends suelen ir en subredes privadas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-J3', 'CLD-02', 'Junior', 'fill', 'Un ___ es un firewall a nivel de instancia que controla el tráfico de entrada y salida.', null, 'Security Group', array['Internet Gateway', 'Route Table', 'Load Balancer']::text[], 'Los Security Groups son stateful: si permites la entrada, la respuesta sale automáticamente.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-J4', 'CLD-02', 'Junior', 'open', 'Explica cómo llega una petición de un usuario a una aplicación web en AWS.', 'Explain how a user''s request reaches a web application on AWS.', null, '{}'::text[], null, null, null, 'DNS (Route 53) resolves domain; optionally CDN (CloudFront); load balancer in public subnet; security groups; app servers/containers in private subnets; database in private subnet; response back', 'The user types the domain, and Route 53 resolves it. The request can go first through CloudFront, a CDN. Then it reaches an Application Load Balancer in a public subnet, which forwards it to the application servers or containers in private subnets, allowed by the security groups. The application queries the database, also in a private subnet, and the response goes back the same way.', 'El usuario escribe el dominio y Route 53 lo resuelve. La petición puede pasar primero por CloudFront, un CDN. Después llega a un Application Load Balancer en una subred pública, que la reenvía a los servidores o contenedores de la aplicación en subredes privadas, permitido por los security groups. La aplicación consulta la base de datos, también en una subred privada, y la respuesta vuelve por el mismo camino.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-M1', 'CLD-02', 'Mid', 'mc', '¿Para qué sirve un NAT Gateway?', null, 'Para que recursos en subredes privadas salgan a internet (p. ej. actualizaciones) sin ser accesibles desde fuera', array['Para recibir tráfico de internet', 'Para conectar dos regiones', 'Para balancear carga']::text[], 'Ojo: tiene coste por hora y por GB procesado.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-M2', 'CLD-02', 'Mid', 'mc', '¿Diferencia entre Security Group y Network ACL?', null, 'El SG actúa a nivel de instancia y es stateful; la NACL actúa a nivel de subred y es stateless', array['Son lo mismo', 'La NACL es a nivel de instancia', 'El SG es stateless']::text[], 'En la NACL hay que permitir explícitamente también el tráfico de vuelta.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-M3', 'CLD-02', 'Mid', 'mc', '¿Qué balanceador elegirías para enrutar por ruta HTTP (/api, /web)?', null, 'Application Load Balancer', array['Network Load Balancer', 'Gateway Load Balancer', 'Classic Load Balancer']::text[], 'El ALB trabaja en capa 7; el NLB en capa 4 con latencia ultrabaja.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-M4', 'CLD-02', 'Mid', 'open', '¿Cómo diseñarías la red de una aplicación de tres capas en AWS?', 'How would you design the network for a three-tier application on AWS?', null, '{}'::text[], null, null, null, 'VPC across at least two AZs; public subnets for ALB and NAT; private subnets for app; isolated/private subnets for DB; security groups chaining (ALB→app→DB); NACLs; VPC endpoints for S3; flow logs', 'I''d create a VPC spread across at least two availability zones. Public subnets hold the load balancer and the NAT gateways. Private subnets hold the application, and separate private subnets hold the database. Security groups are chained: the load balancer can reach the app, and only the app can reach the database. I''d add VPC endpoints for services like S3 and enable flow logs for troubleshooting.', 'Crearía una VPC repartida en al menos dos zonas de disponibilidad. Las subredes públicas tendrían el balanceador y los NAT gateways. Las subredes privadas, la aplicación, y otras subredes privadas separadas, la base de datos. Los security groups irían encadenados: el balanceador llega a la aplicación y solo la aplicación llega a la base de datos. Añadiría VPC endpoints para servicios como S3 y activaría los flow logs para diagnosticar problemas.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-S1', 'CLD-02', 'Senior', 'mc', '¿Qué solución conecta muchas VPCs y redes on-premise de forma centralizada?', null, 'AWS Transit Gateway', array['VPC Peering entre todas', 'Un NAT Gateway', 'CloudFront']::text[], 'El peering no es transitivo: con muchas VPCs se vuelve inmanejable.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-S2', 'CLD-02', 'Senior', 'mc', '¿Qué ventaja tienen los VPC endpoints?', null, 'Acceder a servicios de AWS desde subredes privadas sin salir a internet ni pasar por NAT', array['Aumentan el ancho de banda de internet', 'Sustituyen a los Security Groups', 'Son obligatorios']::text[], 'Mejoran la seguridad y pueden ahorrar coste de NAT.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-S3', 'CLD-02', 'Senior', 'mc', '¿Cuándo usarías Direct Connect en lugar de una VPN Site-to-Site?', null, 'Cuando necesitas una conexión dedicada con ancho de banda y latencia más estables', array['Siempre, es más barato', 'Para conectar dos VPCs', 'Para usuarios remotos']::text[], 'La VPN es rápida de montar; Direct Connect tarda semanas pero es más estable.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-02-S4', 'CLD-02', 'Senior', 'open', '¿Cómo plantearías una arquitectura de red híbrida entre un CPD y AWS?', 'How would you approach a hybrid network architecture between an on-premise data center and AWS?', null, '{}'::text[], null, null, null, 'connectivity: Site-to-Site VPN and/or Direct Connect with VPN backup; Transit Gateway hub; non-overlapping CIDR planning; Route 53 Resolver for hybrid DNS; security and segmentation; monitoring', 'First I''d plan the IP ranges so they don''t overlap. For connectivity, Direct Connect for stable bandwidth, with a Site-to-Site VPN as backup. A Transit Gateway as the central hub connecting the VPCs and the data center. Route 53 Resolver endpoints for DNS in both directions. And clear segmentation with route tables and security groups, plus monitoring of the links.', 'Primero planificaría los rangos de IP para que no se solapen. Para la conectividad, Direct Connect para un ancho de banda estable, con una VPN Site-to-Site de respaldo. Un Transit Gateway como nodo central que conecte las VPC y el centro de datos. Endpoints de Route 53 Resolver para el DNS en ambas direcciones. Y una segmentación clara con tablas de rutas y security groups, además de monitorizar los enlaces.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-J1', 'CLD-03', 'Junior', 'mc', '¿Qué es un contenedor?', null, 'Un paquete con la aplicación y sus dependencias que se ejecuta aislado compartiendo el kernel del sistema', array['Una máquina virtual completa', 'Un servidor físico', 'Un lenguaje de programación']::text[], 'Es más ligero que una VM porque no incluye un sistema operativo completo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-J2', 'CLD-03', 'Junior', 'fill', 'Las instrucciones para construir una imagen de Docker se escriben en un ___.', null, 'Dockerfile', array['docker-compose.yml', 'package.json', 'Makefile']::text[], 'docker build lo lee y genera la imagen.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-J3', 'CLD-03', 'Junior', 'mc', '¿Diferencia entre imagen y contenedor?', null, 'La imagen es la plantilla inmutable; el contenedor es una instancia en ejecución de esa imagen', array['Son lo mismo', 'El contenedor es la plantilla', 'La imagen solo existe en producción']::text[], 'Como una clase (imagen) y sus objetos (contenedores).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-J4', 'CLD-03', 'Junior', 'open', '¿Qué ventajas aporta Docker a un equipo de desarrollo?', 'What advantages does Docker bring to a development team?', null, '{}'::text[], null, null, null, 'same environment everywhere (works on my machine); fast setup; isolation; reproducible builds; easier CI/CD; portability across clouds', 'Docker gives everyone the same environment, from a developer''s laptop to production, so you avoid the ''it works on my machine'' problem. New people can run the whole project with one command. Each service is isolated with its own dependencies, builds are reproducible, and the same image can run in CI, on any cloud or on Kubernetes.', 'Docker da a todo el mundo el mismo entorno, desde el portátil de un desarrollador hasta producción, y evita el problema de «en mi máquina funciona». Las personas nuevas pueden arrancar todo el proyecto con un comando. Cada servicio está aislado con sus dependencias, los builds son reproducibles y la misma imagen puede ejecutarse en CI, en cualquier nube o en Kubernetes.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-M1', 'CLD-03', 'Mid', 'mc', '¿Qué ventaja tiene un build multi-stage en Docker?', null, 'Imágenes finales más pequeñas y seguras, sin herramientas de compilación', array['Builds más lentos pero más bonitos', 'Permite usar varios Dockerfiles', 'Ninguna']::text[], 'Compilas en una etapa y copias solo el resultado a una imagen base mínima.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-M2', 'CLD-03', 'Mid', 'mc', 'En Kubernetes, ¿qué es un Deployment?', null, 'Un objeto que mantiene un número de réplicas de pods y gestiona sus actualizaciones', array['Un servidor físico', 'Una imagen de Docker', 'Un balanceador externo']::text[], 'Si un pod muere, el Deployment crea otro.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-M3', 'CLD-03', 'Mid', 'mc', '¿Qué hace un Service de Kubernetes?', null, 'Da una dirección estable para acceder a un grupo de pods y reparte el tráfico entre ellos', array['Construye imágenes', 'Guarda secretos', 'Escala los nodos']::text[], 'Los pods cambian de IP; el Service no.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-M4', 'CLD-03', 'Mid', 'open', '¿Cuándo elegirías ECS con Fargate y cuándo EKS?', 'When would you choose ECS with Fargate and when EKS?', null, '{}'::text[], null, null, null, 'ECS/Fargate: simpler, AWS-native, no cluster management, smaller teams; EKS: Kubernetes standard, portability, ecosystem (Helm, operators), complex workloads, team with K8s skills, more operational cost', 'I''d choose ECS with Fargate when the team wants something simple and AWS-native: no cluster or nodes to manage, and it integrates well with the rest of AWS. I''d choose EKS when we need Kubernetes specifically, for portability between clouds, the ecosystem like Helm and operators, or because the team already has Kubernetes experience. EKS is more powerful but has a higher operational cost.', 'Elegiría ECS con Fargate cuando el equipo quiere algo sencillo y nativo de AWS: sin clúster ni nodos que gestionar y bien integrado con el resto de AWS. Elegiría EKS cuando necesitamos Kubernetes específicamente, por portabilidad entre nubes, por su ecosistema como Helm y los operadores, o porque el equipo ya tiene experiencia con Kubernetes. EKS es más potente, pero tiene más coste operativo.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-S1', 'CLD-03', 'Senior', 'mc', '¿Qué hacen las readiness y liveness probes?', null, 'Readiness indica si el pod puede recibir tráfico; liveness, si hay que reiniciarlo', array['Son lo mismo', 'Miden el coste', 'Solo sirven en desarrollo']::text[], 'Una liveness mal configurada puede provocar reinicios en cadena.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-S2', 'CLD-03', 'Senior', 'mc', '¿Para qué sirve el Horizontal Pod Autoscaler?', null, 'Para aumentar o reducir el número de pods según métricas como CPU o métricas propias', array['Para añadir CPU a un pod', 'Para crear nodos nuevos directamente', 'Para hacer backups']::text[], 'Para escalar nodos se usa Cluster Autoscaler o Karpenter.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-S3', 'CLD-03', 'Senior', 'mc', '¿Cómo gestionarías secretos en Kubernetes en AWS de forma segura?', null, 'Guardarlos en Secrets Manager o Parameter Store y sincronizarlos (p. ej. External Secrets) con permisos por pod', array['En variables de entorno dentro de la imagen', 'En el repositorio cifrados en base64', 'En un ConfigMap']::text[], 'Base64 no es cifrado. IRSA o Pod Identity dan permisos de IAM por pod.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-03-S4', 'CLD-03', 'Senior', 'open', '¿Cómo harías un despliegue sin caída de servicio de una aplicación en contenedores?', 'How would you deploy a containerized application with zero downtime?', null, '{}'::text[], null, null, null, 'rolling update with proper readiness probes; or blue/green or canary (CodeDeploy, Argo Rollouts); backward-compatible DB migrations; health checks; automatic rollback on metrics; graceful shutdown', 'I''d use a rolling update, or for critical services a blue/green or canary deployment. The key is good readiness probes, so traffic only goes to healthy pods, and graceful shutdown, so pods finish their requests before stopping. Database migrations must be backward compatible. And I''d watch error rates and latency during the rollout, with automatic rollback if they get worse.', 'Usaría un rolling update o, para servicios críticos, un despliegue blue/green o canary. La clave son unas buenas readiness probes, para que el tráfico solo vaya a pods sanos, y un apagado ordenado, para que los pods terminen sus peticiones antes de parar. Las migraciones de base de datos tienen que ser compatibles hacia atrás. Y vigilaría la tasa de errores y la latencia durante el despliegue, con vuelta atrás automática si empeoran.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-J1', 'CLD-04', 'Junior', 'mc', '¿Qué es CI (integración continua)?', null, 'Integrar cambios con frecuencia y validarlos automáticamente con build y tests', array['Desplegar a mano los viernes', 'Un tipo de servidor', 'Una metodología de diseño']::text[], 'CD (entrega o despliegue continuo) lleva esos cambios hasta los entornos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-J2', 'CLD-04', 'Junior', 'mc', '¿Qué es la infraestructura como código (IaC)?', null, 'Definir la infraestructura en archivos versionados y crearla de forma automática', array['Programar dentro de los servidores', 'Documentar la infraestructura en Word', 'Usar solo la consola web']::text[], 'Herramientas: Terraform, CloudFormation, CDK.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-J3', 'CLD-04', 'Junior', 'fill', 'En Terraform, el comando que muestra qué cambios se van a aplicar sin aplicarlos es terraform ___.', null, 'plan', array['apply', 'init', 'show']::text[], 'init prepara, plan previsualiza y apply ejecuta.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-J4', 'CLD-04', 'Junior', 'open', 'Describe un pipeline de CI/CD típico.', 'Describe a typical CI/CD pipeline.', null, '{}'::text[], null, null, null, 'trigger on push/PR; install dependencies; lint; tests; build artifact/image; security scan; push to registry; deploy to staging; tests; approval; deploy to production; notifications', 'When someone pushes code or opens a pull request, the pipeline starts. It installs dependencies, runs the linter and the tests, and builds the artifact or Docker image. Then a security scan, and the image is pushed to a registry. It deploys automatically to a staging environment, runs some tests there, and after an approval it deploys to production. The team gets notified if anything fails.', 'Cuando alguien sube código o abre una pull request, arranca el pipeline. Instala las dependencias, pasa el linter y los tests, y construye el artefacto o la imagen de Docker. Después hace un análisis de seguridad y sube la imagen a un registro. Despliega automáticamente en un entorno de preproducción, ejecuta algunas pruebas ahí y, tras una aprobación, despliega en producción. El equipo recibe un aviso si algo falla.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-M1', 'CLD-04', 'Mid', 'mc', '¿Qué es el state de Terraform y dónde guardarlo en equipo?', null, 'El registro de lo que Terraform gestiona; se guarda en un backend remoto (S3) con bloqueo', array['Una variable de entorno', 'Se guarda en el repositorio sin problema', 'No hace falta guardarlo']::text[], 'Sin bloqueo, dos personas pueden aplicar a la vez y corromperlo. El state puede contener secretos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-M2', 'CLD-04', 'Mid', 'mc', '¿Qué es el ''drift'' en infraestructura?', null, 'Diferencias entre lo definido en código y lo que existe realmente, por cambios manuales', array['Un tipo de despliegue', 'Un error de red', 'La latencia entre regiones']::text[], 'Se detecta con terraform plan periódicos o detección de drift de CloudFormation.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-M3', 'CLD-04', 'Mid', 'mc', '¿Cómo se autentica de forma segura un pipeline de GitHub Actions en AWS?', null, 'Con OIDC asumiendo un rol de IAM, sin claves de larga duración', array['Con las claves del usuario root', 'Con claves de acceso guardadas en el código', 'No necesita autenticarse']::text[], 'OIDC da credenciales temporales por ejecución.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-M4', 'CLD-04', 'Mid', 'open', '¿Cómo organizarías el código Terraform para varios entornos?', 'How would you organize Terraform code for several environments?', null, '{}'::text[], null, null, null, 'reusable modules; separate state per environment; environment folders or workspaces with tfvars; remote backend with locking; pipeline running plan on PR and apply after approval; version pinning', 'I''d write reusable modules for the common pieces, like the network or a service, and then one configuration per environment that uses those modules with different variables. Each environment has its own remote state in S3 with locking. The pipeline runs terraform plan on every pull request so reviewers see the changes, and apply only after approval. And I''d pin the provider and module versions.', 'Escribiría módulos reutilizables para las piezas comunes, como la red o un servicio, y una configuración por entorno que use esos módulos con distintas variables. Cada entorno tiene su propio state remoto en S3 con bloqueo. El pipeline ejecuta terraform plan en cada pull request para que se vean los cambios en la revisión, y apply solo tras la aprobación. Y fijaría las versiones de los providers y de los módulos.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-S1', 'CLD-04', 'Senior', 'mc', '¿Qué es GitOps?', null, 'Usar Git como fuente de verdad del estado deseado; un agente (Argo CD, Flux) sincroniza el clúster con el repositorio', array['Hacer commits directamente en producción', 'Una herramienta de Git', 'Un tipo de rama']::text[], 'Cada cambio queda auditado y revertir es hacer revert.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-S2', 'CLD-04', 'Senior', 'mc', '¿Qué diferencia hay entre despliegue canary y blue/green?', null, 'Canary manda un porcentaje creciente de tráfico a la versión nueva; blue/green cambia todo el tráfico de un entorno completo a otro', array['Son lo mismo', 'Canary no usa tráfico real', 'Blue/green solo sirve para bases de datos']::text[], 'Ambos permiten revertir rápido; canary limita el impacto de un error.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-S3', 'CLD-04', 'Senior', 'mc', '¿Qué son las métricas DORA?', null, 'Frecuencia de despliegue, lead time de cambios, tasa de fallos en cambios y tiempo de recuperación', array['Métricas de coste en AWS', 'Indicadores de seguridad de red', 'Métricas de uso de CPU']::text[], 'Miden el rendimiento de la entrega de software de un equipo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-04-S4', 'CLD-04', 'Senior', 'open', '¿Cómo mejorarías un proceso de despliegue lento y manual en una empresa?', 'How would you improve a slow and manual deployment process in a company?', null, '{}'::text[], null, null, null, 'measure current state (DORA); automate build/test first; infrastructure as code; standard pipeline templates; smaller and more frequent releases; feature flags; progressive delivery; automated rollback; involve teams, change culture gradually', 'First I''d measure the current situation, for example with the DORA metrics, and talk to the teams about the pain points. Then I''d automate step by step: builds and tests first, then infrastructure as code, then deployments with standard pipeline templates. I''d push for smaller, more frequent releases, with feature flags and canary deployments to reduce risk. The cultural part matters as much as the tools.', 'Primero mediría la situación actual, por ejemplo con las métricas DORA, y hablaría con los equipos sobre los puntos de dolor. Después automatizaría paso a paso: primero builds y tests, luego infraestructura como código y luego despliegues con plantillas de pipeline estándar. Impulsaría releases más pequeñas y frecuentes, con feature flags y despliegues canary para reducir el riesgo. La parte cultural importa tanto como las herramientas.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-J1', 'CLD-05', 'Junior', 'mc', '¿Qué comando muestra los procesos en ejecución?', null, 'ps (o top / htop)', array['ls', 'cd', 'chmod']::text[], 'top y htop se actualizan en tiempo real.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-J2', 'CLD-05', 'Junior', 'fill', 'Para dar permisos de ejecución a un script se usa ___ +x script.sh.', null, 'chmod', array['chown', 'sudo', 'mv']::text[], 'chown cambia el propietario; chmod, los permisos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-J3', 'CLD-05', 'Junior', 'mc', '¿Qué hace `tail -f /var/log/app.log`?', null, 'Muestra el final del archivo y sigue mostrando las líneas nuevas en tiempo real', array['Borra el log', 'Muestra el principio del archivo', 'Comprime el log']::text[], 'Muy útil para seguir logs mientras reproduces un problema.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-J4', 'CLD-05', 'Junior', 'open', '¿Cómo comprobarías por qué un servidor Linux va lento?', 'How would you check why a Linux server is slow?', null, '{}'::text[], null, null, null, 'top/htop for CPU and memory; free -h; df -h for disk space; iostat for disk I/O; check logs; network (ss, ping); identify the process', 'I''d start with top or htop to see CPU and memory usage and which process is using them. Then free to check memory and swap, df to check if a disk is full, and iostat if I suspect disk activity. I''d look at the system and application logs, and check the network if it seems related. The goal is to find which resource is the bottleneck and which process causes it.', 'Empezaría con top o htop para ver el uso de CPU y memoria y qué proceso los consume. Después free para revisar la memoria y el swap, df para ver si algún disco está lleno, e iostat si sospecho de la actividad del disco. Miraría los logs del sistema y de la aplicación, y revisaría la red si parece relacionado. El objetivo es encontrar qué recurso es el cuello de botella y qué proceso lo provoca.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-M1', 'CLD-05', 'Mid', 'mc', '¿Qué hace `set -euo pipefail` al principio de un script de Bash?', null, 'Hace que el script falle ante errores, variables no definidas y fallos dentro de pipes', array['Activa el modo debug', 'Hace el script más rápido', 'Lo ejecuta como root']::text[], 'Evita que un script siga adelante tras un fallo silencioso.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-M2', 'CLD-05', 'Mid', 'mc', '¿Con qué gestionas un servicio en un Linux moderno?', null, 'systemctl (systemd)', array['crontab', 'apt', 'ssh']::text[], 'systemctl status/start/restart/enable, y journalctl para sus logs.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-M3', 'CLD-05', 'Mid', 'mc', '¿Qué hace `grep -r "ERROR" /var/log | wc -l`?', null, 'Cuenta las líneas que contienen ERROR en los logs, de forma recursiva', array['Borra los errores', 'Muestra solo el primer error', 'Comprime los logs']::text[], 'Las tuberías encadenan comandos pequeños.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-M4', 'CLD-05', 'Mid', 'open', 'Escribiste un script que funciona a mano pero falla en un cron. ¿Qué revisarías?', 'You wrote a script that works manually but fails in cron. What would you check?', null, '{}'::text[], null, null, null, 'cron has minimal environment: PATH and variables; use absolute paths; working directory; permissions and user; redirect output to a log to see errors; shebang', 'Cron runs with a very minimal environment, so the first thing I''d check is the PATH and environment variables: I''d use absolute paths for commands and files. Also the working directory, which isn''t the same as when I run it by hand, and the user and permissions. And I''d redirect the output and errors to a log file, so I can see what''s actually failing.', 'Cron se ejecuta con un entorno mínimo, así que lo primero es revisar el PATH y las variables de entorno: usaría rutas absolutas para comandos y archivos. También el directorio de trabajo, que no es el mismo que cuando lo lanzo a mano, y el usuario y los permisos. Y redirigiría la salida y los errores a un archivo de log para ver qué falla realmente.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-S1', 'CLD-05', 'Senior', 'mc', '¿Qué indica un load average alto con CPU casi ociosa?', null, 'Procesos esperando I/O (disco o red), por ejemplo en estado D', array['Que todo va bien', 'Que falta CPU', 'Que el kernel está desactualizado']::text[], 'El load average cuenta también procesos bloqueados esperando I/O.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-S2', 'CLD-05', 'Senior', 'mc', '¿Qué herramienta usarías para ver qué llamadas al sistema hace un proceso?', null, 'strace', array['ls', 'cat', 'uptime']::text[], 'Útil para depurar procesos que se cuelgan o fallan sin log.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-S3', 'CLD-05', 'Senior', 'mc', '¿Por qué preferir herramientas de gestión de configuración o imágenes inmutables a conectarse por SSH a cambiar cosas?', null, 'Cambios reproducibles, auditables y sin servidores ''copo de nieve'' distintos entre sí', array['Porque SSH es lento', 'Porque SSH está prohibido en AWS', 'No hay diferencia']::text[], 'Con SSM Session Manager ni siquiera hace falta abrir el puerto 22.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-05-S4', 'CLD-05', 'Senior', 'open', 'Cuéntame cómo automatizarías tareas operativas repetitivas en una plataforma.', 'Tell me how you would automate repetitive operational tasks on a platform.', null, '{}'::text[], null, null, null, 'identify toil and measure it; scripts in version control with tests; idempotent automation; runbooks as code (SSM Automation, Lambda); event-driven remediation; logging and alerts; self-service for developers', 'I''d first identify the toil: the manual tasks the team repeats most and how much time they take. Then automate them with versioned, idempotent scripts, or with tools like SSM Automation or Lambda triggered by events, for example to restart a service or clean up disks automatically. Everything logged and with alerts if the automation fails. And where possible, I''d give developers self-service tools, so they don''t need to open tickets.', 'Primero identificaría el trabajo manual repetitivo: las tareas que más repite el equipo y cuánto tiempo consumen. Después las automatizaría con scripts versionados e idempotentes, o con herramientas como SSM Automation o Lambda activadas por eventos, por ejemplo para reiniciar un servicio o limpiar discos automáticamente. Todo con logs y alertas si la automatización falla. Y, donde se pueda, daría herramientas de autoservicio a los desarrolladores para que no tengan que abrir tickets.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-J1', 'CLD-06', 'Junior', 'mc', '¿Qué servicio de AWS recoge métricas, logs y alarmas?', null, 'Amazon CloudWatch', array['Amazon S3', 'AWS IAM', 'Amazon Route 53']::text[], 'CloudTrail, en cambio, registra quién hizo qué llamada a la API.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-J2', 'CLD-06', 'Junior', 'mc', '¿Qué son los tres pilares de la observabilidad?', null, 'Logs, métricas y trazas', array['CPU, memoria y disco', 'Dev, QA y producción', 'Alarmas, emails y SMS']::text[], 'Las trazas siguen una petición a través de varios servicios.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-J3', 'CLD-06', 'Junior', 'fill', 'Una alarma de CloudWatch puede enviar notificaciones a través de ___.', null, 'SNS', array['S3', 'EBS', 'VPC']::text[], 'SNS reparte el aviso por email, SMS, Slack (vía integraciones) o Lambda.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-J4', 'CLD-06', 'Junior', 'open', '¿Qué harías si te avisan de que la web de producción no responde?', 'What would you do if you were told the production website is down?', null, '{}'::text[], null, null, null, 'confirm and assess impact; communicate; check recent changes/deployments; dashboards, health checks, logs; rollback if a deploy caused it; mitigate first, root cause later; postmortem', 'First I''d confirm the problem and its impact, and let the team know I''m on it. Then I''d check what changed recently, because a new deployment is the most common cause, and look at the dashboards, health checks and logs. If a deploy caused it, I''d roll back first and investigate later. The priority is to restore the service, and afterwards do a blameless postmortem to prevent it from happening again.', 'Primero confirmaría el problema y su impacto, y avisaría al equipo de que me ocupo. Después revisaría qué ha cambiado recientemente, porque un despliegue nuevo es la causa más habitual, y miraría los dashboards, los health checks y los logs. Si lo ha provocado un despliegue, volvería atrás primero e investigaría después. La prioridad es recuperar el servicio y, después, hacer un postmortem sin culpables para que no se repita.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-M1', 'CLD-06', 'Mid', 'mc', '¿Qué diferencia hay entre RTO y RPO?', null, 'RTO es cuánto tiempo puedes estar caído; RPO, cuántos datos puedes permitirte perder (medido en tiempo)', array['Son lo mismo', 'RTO mide coste y RPO rendimiento', 'RPO es el tiempo de despliegue']::text[], 'Ambos definen qué estrategia de recuperación ante desastres necesitas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-M2', 'CLD-06', 'Mid', 'mc', '¿Qué hace un Auto Scaling Group con health checks del balanceador?', null, 'Sustituye automáticamente las instancias que dejan de estar sanas', array['Borra la aplicación', 'Solo reduce costes', 'Hace backups']::text[], 'Combinado con varias AZ, da recuperación automática ante fallos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-M3', 'CLD-06', 'Mid', 'mc', '¿Qué es un SLO?', null, 'Un objetivo interno de fiabilidad, por ejemplo 99,9% de peticiones correctas al mes', array['Un contrato con penalizaciones', 'Un tipo de log', 'Una alarma de coste']::text[], 'El SLA es el compromiso contractual; el SLI, la métrica que se mide.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-M4', 'CLD-06', 'Mid', 'open', '¿Qué alarmas configurarías para una API en producción?', 'What alarms would you set up for an API in production?', null, '{}'::text[], null, null, null, 'user-facing symptoms: error rate (5xx), latency (p95/p99), availability; saturation: CPU, memory, connections, queue depth; dependencies (DB); avoid alert fatigue; actionable alerts with runbooks; severity levels', 'I''d focus on symptoms that users notice: the error rate, especially 5xx responses, latency at p95 or p99, and availability. Then saturation metrics like CPU, memory, database connections or queue depth, which warn before things break. Every alert should be actionable and link to a runbook, with different severity levels, so the team doesn''t get alert fatigue.', 'Me centraría en los síntomas que notan los usuarios: la tasa de errores, sobre todo respuestas 5xx, la latencia en p95 o p99 y la disponibilidad. Después, métricas de saturación como CPU, memoria, conexiones a la base de datos o profundidad de las colas, que avisan antes de que algo se rompa. Cada alerta debe permitir actuar y enlazar a un runbook, con distintos niveles de gravedad, para que el equipo no acabe saturado de alertas.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-S1', 'CLD-06', 'Senior', 'mc', '¿Qué es el error budget?', null, 'El margen de fallos que permite el SLO; si se agota, se prioriza la fiabilidad sobre funcionalidades nuevas', array['El presupuesto para comprar servidores', 'Un tipo de alarma', 'El número de bugs permitidos en QA']::text[], 'Equilibra la velocidad de desarrollo y la estabilidad.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-S2', 'CLD-06', 'Senior', 'mc', '¿Qué estrategia de DR tiene menor RTO?', null, 'Multi-site activo-activo', array['Backup and restore', 'Pilot light', 'Warm standby']::text[], 'También es la más cara. De más barata a más rápida: backup, pilot light, warm standby, activo-activo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-S3', 'CLD-06', 'Senior', 'mc', '¿Qué es el chaos engineering?', null, 'Introducir fallos controlados para comprobar que el sistema resiste como se espera', array['Desplegar sin tests', 'Romper producción sin avisar', 'Un tipo de monitorización']::text[], 'AWS Fault Injection Service permite hacerlo de forma controlada.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('CLD-06-S4', 'CLD-06', 'Senior', 'open', '¿Cómo diseñarías una arquitectura de alta disponibilidad para una aplicación crítica?', 'How would you design a high-availability architecture for a critical application?', null, '{}'::text[], null, null, null, 'eliminate single points of failure; multi-AZ for compute and database (RDS Multi-AZ/Aurora); load balancer and auto scaling; stateless services; queues to decouple; backups and DR plan with RTO/RPO; multi-region if needed; health checks; observability; test failures', 'I''d remove single points of failure: stateless services behind a load balancer with auto scaling across at least two availability zones, and a database with Multi-AZ, like Aurora. I''d decouple components with queues, so a slow service doesn''t bring everything down. A disaster recovery plan based on the agreed RTO and RPO, and multiple regions only if the business needs it. Plus good observability and regular failure tests to make sure it really works.', 'Eliminaría los puntos únicos de fallo: servicios sin estado detrás de un balanceador con autoescalado en al menos dos zonas de disponibilidad, y una base de datos Multi-AZ, como Aurora. Desacoplaría componentes con colas, para que un servicio lento no tumbe todo. Un plan de recuperación ante desastres según el RTO y el RPO acordados, y varias regiones solo si el negocio lo necesita. Además, buena observabilidad y pruebas de fallos periódicas para asegurar que realmente funciona.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-J1', 'BCK-01', 'Junior', 'mc', '¿Diferencia entre `==` y `equals()` con objetos?', null, '== compara referencias; equals() compara el contenido (si está bien implementado)', array['Son iguales', 'equals() compara referencias', '== solo funciona con Strings']::text[], 'Clásico con Strings: usa siempre equals().', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-J2', 'BCK-01', 'Junior', 'mc', '¿Qué colección usarías para no tener elementos repetidos?', null, 'Set (por ejemplo HashSet)', array['ArrayList', 'LinkedList', 'Array']::text[], 'Un Map guarda pares clave-valor con claves únicas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-J3', 'BCK-01', 'Junior', 'fill', 'Una excepción que el compilador obliga a capturar o declarar es una excepción ___.', null, 'checked', array['unchecked', 'runtime', 'final']::text[], 'IOException es checked; NullPointerException es unchecked (RuntimeException).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-J4', 'BCK-01', 'Junior', 'open', '¿Qué son los cuatro pilares de la programación orientada a objetos?', 'What are the four pillars of object-oriented programming?', null, '{}'::text[], null, null, null, 'encapsulation, inheritance, polymorphism, abstraction; short example of each', 'The four pillars are encapsulation, which means hiding the internal state and exposing methods; inheritance, which lets a class reuse another class''s behaviour; polymorphism, which lets you treat different objects through the same interface; and abstraction, which means exposing only what''s necessary and hiding the details.', 'Los cuatro pilares son la encapsulación, que consiste en ocultar el estado interno y exponer métodos; la herencia, que permite a una clase reutilizar el comportamiento de otra; el polimorfismo, que permite tratar objetos distintos a través de la misma interfaz; y la abstracción, que consiste en exponer solo lo necesario y ocultar los detalles.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-M1', 'BCK-01', 'Mid', 'mc', 'Si sobrescribes `equals()`, ¿qué más debes sobrescribir?', null, 'hashCode()', array['toString()', 'finalize()', 'clone()']::text[], 'Si no, los objetos iguales irían a buckets distintos en un HashMap.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-M2', 'BCK-01', 'Mid', 'mc', '¿Qué hace `Optional`?', null, 'Representa un valor que puede o no existir, para evitar null y NullPointerException', array['Hace un campo opcional en la base de datos', 'Optimiza el rendimiento', 'Sustituye a las excepciones']::text[], 'Úsalo sobre todo como tipo de retorno, no en campos ni parámetros.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-M3', 'BCK-01', 'Mid', 'mc', '¿Qué hace este código: `list.stream().filter(x -> x > 5).map(x -> x * 2).toList()`?', null, 'Filtra los mayores que 5, los duplica y devuelve una lista nueva', array['Modifica la lista original', 'Devuelve un número', 'Lanza una excepción']::text[], 'Los streams no modifican la colección original.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-M4', 'BCK-01', 'Mid', 'open', '¿Qué novedades de Java moderno (17 o posterior) usas o conoces?', 'What features of modern Java (17 or later) do you use or know?', null, '{}'::text[], null, null, null, 'records; sealed classes; pattern matching for instanceof and switch; text blocks; var; virtual threads (21); sequenced collections', 'I like records for immutable data classes, because they remove a lot of boilerplate. Pattern matching for instanceof and switch makes the code cleaner, and sealed classes let you control which classes can extend a type. Text blocks are useful for SQL or JSON. And in Java 21, virtual threads make it much easier to handle many concurrent requests.', 'Me gustan los records para clases de datos inmutables, porque eliminan mucho código repetitivo. El pattern matching en instanceof y switch hace el código más limpio, y las sealed classes permiten controlar qué clases pueden extender un tipo. Los text blocks son útiles para SQL o JSON. Y en Java 21, los virtual threads facilitan mucho atender muchas peticiones concurrentes.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-S1', 'BCK-01', 'Senior', 'mc', '¿Qué aportan los virtual threads de Java 21?', null, 'Hilos muy ligeros gestionados por la JVM que permiten miles de tareas concurrentes bloqueantes sin agotar recursos', array['Hacen el código más rápido en CPU', 'Sustituyen a la base de datos', 'Eliminan el garbage collector']::text[], 'Ideales para servicios con mucho I/O; no aceleran el cálculo intensivo.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-S2', 'BCK-01', 'Senior', 'mc', 'Una aplicación consume cada vez más memoria hasta caerse. ¿Qué harías primero?', null, 'Sacar un heap dump y analizarlo (p. ej. con Eclipse MAT) para ver qué objetos se acumulan', array['Aumentar la memoria sin más', 'Reiniciar cada noche', 'Cambiar a otro lenguaje']::text[], 'Fugas típicas: cachés sin límite, listeners sin eliminar, colecciones estáticas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-S3', 'BCK-01', 'Senior', 'mc', '¿Qué colección es segura para acceso concurrente y eficiente?', null, 'ConcurrentHashMap', array['HashMap', 'TreeMap', 'ArrayList']::text[], 'Collections.synchronizedMap también es segura, pero bloquea todo el mapa.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-01-S4', 'BCK-01', 'Senior', 'open', '¿Cómo afrontarías problemas de concurrencia en una aplicación Java?', 'How would you deal with concurrency problems in a Java application?', null, '{}'::text[], null, null, null, 'prefer immutability and stateless services; thread-safe collections; avoid shared mutable state; synchronized/locks only when needed; atomic classes; executors/CompletableFuture/virtual threads; database-level locking; testing and thread dumps', 'My first rule is to avoid shared mutable state: immutable objects and stateless services remove most problems. When state must be shared, I use thread-safe structures like ConcurrentHashMap or atomic classes, and locks only where really needed. For async work I use executors, CompletableFuture or virtual threads. And for data consistency, often the right place is the database, with transactions or optimistic locking.', 'Mi primera regla es evitar el estado mutable compartido: los objetos inmutables y los servicios sin estado eliminan la mayoría de los problemas. Cuando hay que compartir estado, uso estructuras seguras para hilos como ConcurrentHashMap o las clases atómicas, y bloqueos solo donde son realmente necesarios. Para trabajo asíncrono uso executors, CompletableFuture o virtual threads. Y para la consistencia de los datos, a menudo el sitio correcto es la base de datos, con transacciones o bloqueo optimista.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-J1', 'BCK-02', 'Junior', 'mc', '¿Qué hace la anotación `@SpringBootApplication`?', null, 'Combina configuración, autoconfiguración y escaneo de componentes para arrancar la aplicación', array['Crea la base de datos', 'Define un endpoint', 'Hace los tests']::text[], 'Incluye @Configuration, @EnableAutoConfiguration y @ComponentScan.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-J2', 'BCK-02', 'Junior', 'mc', '¿Qué forma de inyectar dependencias se recomienda en Spring?', null, 'Por constructor', array['Con @Autowired en campos privados', 'Con new dentro de la clase', 'Con variables estáticas']::text[], 'Facilita los tests y permite campos final.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-J3', 'BCK-02', 'Junior', 'fill', 'Para marcar una clase de lógica de negocio como bean de Spring se usa ___.', null, '@Service', array['@Entity', '@Value', '@Bean']::text[], '@Component es la genérica; @Service, @Repository y @Controller son especializaciones.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-J4', 'BCK-02', 'Junior', 'open', '¿Qué es Spring Boot y qué aporta frente a Spring ''clásico''?', 'What is Spring Boot and what does it add compared to ''classic'' Spring?', null, '{}'::text[], null, null, null, 'autoconfiguration; starters; embedded server; convention over configuration; production-ready features with Actuator; less XML/boilerplate', 'Spring Boot is built on top of Spring to make it much faster to start a project. It gives you autoconfiguration based on the dependencies you add, starters that group common libraries, and an embedded server, so you just run a jar. It follows convention over configuration, and with Actuator you get health checks and metrics ready for production.', 'Spring Boot se construye sobre Spring para que arrancar un proyecto sea mucho más rápido. Te da autoconfiguración según las dependencias que añades, starters que agrupan librerías habituales y un servidor embebido, así que solo ejecutas un jar. Sigue el principio de convención sobre configuración, y con Actuator tienes health checks y métricas listos para producción.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-M1', 'BCK-02', 'Mid', 'mc', '¿Qué ámbito (scope) tiene por defecto un bean de Spring?', null, 'Singleton', array['Prototype', 'Request', 'Session']::text[], 'Por eso los beans no deben guardar estado de una petición en sus campos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-M2', 'BCK-02', 'Mid', 'mc', '¿Para qué sirven los perfiles (`@Profile`, application-dev.yml)?', null, 'Para tener configuración y beans distintos según el entorno', array['Para gestionar usuarios', 'Para medir rendimiento', 'Para crear roles de seguridad']::text[], 'Se activan con spring.profiles.active.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-M3', 'BCK-02', 'Mid', 'mc', '¿Por qué `@Transactional` puede no funcionar al llamar a un método de la misma clase?', null, 'Porque funciona mediante un proxy, y la llamada interna no pasa por él', array['Porque solo funciona en métodos estáticos', 'Porque necesita XML', 'Siempre funciona']::text[], 'Solución: mover el método a otro bean o reestructurar.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-M4', 'BCK-02', 'Mid', 'open', 'Explica cómo funciona la autoconfiguración de Spring Boot.', 'Explain how Spring Boot autoconfiguration works.', null, '{}'::text[], null, null, null, 'autoconfiguration classes loaded from the classpath; conditional annotations (@ConditionalOnClass, @ConditionalOnMissingBean, @ConditionalOnProperty); you can override with your own beans or properties; debug report', 'Spring Boot ships with many autoconfiguration classes. At startup, it checks conditions: for example, if a database driver is on the classpath and you haven''t defined a DataSource yourself, it creates one using your properties. These conditions use annotations like ConditionalOnClass or ConditionalOnMissingBean. So you can always override the defaults by defining your own bean, and you can see what was applied with the debug report.', 'Spring Boot incluye muchas clases de autoconfiguración. Al arrancar comprueba condiciones: por ejemplo, si hay un driver de base de datos en el classpath y no has definido tú un DataSource, crea uno con tus propiedades. Esas condiciones usan anotaciones como ConditionalOnClass o ConditionalOnMissingBean. Así que siempre puedes sustituir lo que viene por defecto definiendo tu propio bean, y puedes ver qué se ha aplicado con el informe de depuración.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-S1', 'BCK-02', 'Senior', 'mc', '¿Qué aporta Spring Boot Actuator en producción?', null, 'Endpoints de salud, métricas, info y más, integrables con Prometheus u otros sistemas', array['Una interfaz gráfica de administración', 'Seguridad automática completa', 'Un ORM']::text[], 'Hay que proteger los endpoints sensibles.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-S2', 'BCK-02', 'Senior', 'mc', '¿Qué ventaja tiene compilar una app Spring con GraalVM a imagen nativa?', null, 'Arranque muy rápido y menos memoria, útil en serverless o contenedores', array['Más rendimiento en cualquier caso', 'Elimina la necesidad de tests', 'Permite usar Java 8']::text[], 'A cambio, builds más lentos y limitaciones con reflexión.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-S3', 'BCK-02', 'Senior', 'mc', '¿Dónde guardarías la configuración sensible (contraseñas, claves) de un servicio Spring en la nube?', null, 'En un gestor de secretos (Vault, AWS Secrets Manager) inyectado en tiempo de ejecución', array['En application.yml dentro del repositorio', 'En el código', 'En un comentario']::text[], 'Nunca secretos en el repositorio, ni siquiera en privado.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-02-S4', 'BCK-02', 'Senior', 'open', '¿Cómo harías que un servicio Spring Boot esté listo para producción?', 'How would you make a Spring Boot service production-ready?', null, '{}'::text[], null, null, null, 'externalized config and secrets; health checks (Actuator) and graceful shutdown; structured logging with correlation IDs; metrics and tracing (Micrometer, OpenTelemetry); error handling; security; resource limits; timeouts/retries/circuit breakers; tests and CI', 'I''d externalize the configuration and keep secrets in a secrets manager. Actuator health endpoints for the load balancer, and graceful shutdown. Structured logs with correlation IDs, metrics with Micrometer and tracing with OpenTelemetry. Consistent error handling and security from the start. Timeouts, retries and circuit breakers for every external call. And good tests running in CI before every deployment.', 'Sacaría la configuración fuera del código y guardaría los secretos en un gestor de secretos. Endpoints de salud de Actuator para el balanceador y apagado ordenado. Logs estructurados con IDs de correlación, métricas con Micrometer y trazas con OpenTelemetry. Gestión de errores coherente y seguridad desde el principio. Timeouts, reintentos y circuit breakers en cada llamada externa. Y buenos tests ejecutándose en CI antes de cada despliegue.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-J1', 'BCK-03', 'Junior', 'mc', '¿Qué método HTTP usarías para crear un recurso nuevo?', null, 'POST', array['GET', 'DELETE', 'HEAD']::text[], 'GET lee, POST crea, PUT reemplaza, PATCH modifica parcialmente, DELETE borra.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-J2', 'BCK-03', 'Junior', 'mc', '¿Qué significa un código de estado 404?', null, 'El recurso no existe', array['Error interno del servidor', 'No autenticado', 'Creado correctamente']::text[], '2xx éxito, 4xx error del cliente, 5xx error del servidor.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-J3', 'BCK-03', 'Junior', 'fill', 'En Spring, para crear un controlador REST que devuelve JSON se usa ___.', null, '@RestController', array['@Controller', '@Service', '@Repository']::text[], '@RestController = @Controller + @ResponseBody.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-J4', 'BCK-03', 'Junior', 'open', '¿Qué es una API REST?', 'What is a REST API?', null, '{}'::text[], null, null, null, 'architectural style over HTTP; resources identified by URLs; HTTP methods; stateless; representations like JSON; status codes', 'A REST API is a way to design web services using HTTP. Each resource, like a user or an order, has a URL, and you use the HTTP methods to work with it: GET to read, POST to create, PUT or PATCH to update and DELETE to remove. It''s stateless, so each request contains all the information needed, data is usually exchanged as JSON, and status codes tell you the result.', 'Una API REST es una forma de diseñar servicios web sobre HTTP. Cada recurso, como un usuario o un pedido, tiene una URL, y se usan los métodos HTTP para trabajar con él: GET para leer, POST para crear, PUT o PATCH para actualizar y DELETE para borrar. No guarda estado entre peticiones, así que cada petición lleva toda la información necesaria; los datos suelen intercambiarse en JSON y los códigos de estado indican el resultado.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-M1', 'BCK-03', 'Mid', 'mc', '¿Qué métodos HTTP son idempotentes?', null, 'GET, PUT y DELETE (repetirlos deja el mismo resultado)', array['Solo POST', 'POST y PATCH', 'Ninguno']::text[], 'POST no es idempotente: repetirlo puede crear duplicados.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-M2', 'BCK-03', 'Mid', 'mc', '¿Cómo gestionarías los errores de forma centralizada en Spring?', null, 'Con @RestControllerAdvice y @ExceptionHandler, devolviendo un formato común (p. ej. ProblemDetail)', array['Con try/catch en cada controlador', 'Devolviendo siempre 200', 'Con System.out.println']::text[], 'ProblemDetail sigue el estándar RFC 9457 para errores HTTP.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-M3', 'BCK-03', 'Mid', 'mc', '¿Para qué sirven los DTOs?', null, 'Para separar lo que expone la API del modelo interno (entidades), controlando qué datos entran y salen', array['Para conectarse a la base de datos', 'Para cifrar datos', 'No sirven para nada']::text[], 'Exponer entidades directamente filtra campos y acopla la API a la base de datos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-M4', 'BCK-03', 'Mid', 'open', '¿Cómo diseñarías la paginación y el versionado de una API?', 'How would you design pagination and versioning for an API?', null, '{}'::text[], null, null, null, 'pagination: page/size or cursor-based for large/changing data, total metadata, limits; versioning: URL (/v1) or header, avoid breaking changes, deprecation policy, documentation (OpenAPI)', 'For pagination, I''d use page and size parameters with a maximum size, and return metadata like the total. For large or constantly changing data, cursor-based pagination is better. For versioning, I prefer a version in the URL, like v1, because it''s simple and visible. The main goal is to avoid breaking changes: add fields instead of changing them, and when a breaking change is needed, publish a new version with a deprecation period, all documented with OpenAPI.', 'Para la paginación usaría parámetros de página y tamaño con un tamaño máximo, y devolvería metadatos como el total. Para datos muy grandes o que cambian constantemente, es mejor la paginación por cursor. Para el versionado prefiero la versión en la URL, como v1, porque es sencilla y visible. El objetivo principal es evitar cambios que rompan a los clientes: añadir campos en lugar de modificarlos y, cuando no haya más remedio, publicar una nueva versión con un periodo de retirada, todo documentado con OpenAPI.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-S1', 'BCK-03', 'Senior', 'mc', '¿Cómo evitas cobros duplicados si el cliente reintenta un POST de pago?', null, 'Con una clave de idempotencia enviada por el cliente y guardada en el servidor', array['Pidiendo al usuario que no pulse dos veces', 'Usando GET en vez de POST', 'Con un timeout más largo']::text[], 'Si llega la misma clave, se devuelve el resultado original sin repetir la operación.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-S2', 'BCK-03', 'Senior', 'mc', '¿Cuándo elegirías gRPC frente a REST?', null, 'Para comunicación interna entre servicios con alto rendimiento y contratos tipados', array['Para APIs públicas consumidas desde el navegador sin más', 'Nunca', 'Solo para archivos grandes']::text[], 'REST sigue siendo lo más cómodo para APIs públicas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-S3', 'BCK-03', 'Senior', 'mc', '¿Qué es el rate limiting y por qué aplicarlo?', null, 'Limitar las peticiones por cliente en un periodo para proteger el servicio de abusos y picos', array['Una forma de cobrar', 'Comprimir respuestas', 'Cachear respuestas']::text[], 'Se suele devolver 429 Too Many Requests.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-03-S4', 'BCK-03', 'Senior', 'open', '¿Cómo diseñarías una API pública que vayan a usar terceros?', 'How would you design a public API that third parties will use?', null, '{}'::text[], null, null, null, 'contract-first with OpenAPI; consistent naming and errors; authentication (OAuth2/API keys); rate limiting and quotas; versioning and deprecation policy; idempotency; pagination; documentation and SDKs; monitoring; security', 'I''d go contract-first: define the API in OpenAPI and review it before writing code. Consistent naming, errors in a standard format, and authentication with OAuth2 or API keys. Rate limiting and quotas per client, idempotency keys for critical operations, and pagination everywhere. A clear versioning and deprecation policy, because external clients can''t update quickly. And good documentation, plus monitoring of how each client uses it.', 'Diseñaría primero el contrato: definir la API en OpenAPI y revisarla antes de escribir código. Nombres coherentes, errores en un formato estándar y autenticación con OAuth2 o API keys. Límites de peticiones y cuotas por cliente, claves de idempotencia para las operaciones críticas y paginación en todas partes. Una política clara de versionado y de retirada, porque los clientes externos no pueden actualizarse rápido. Y buena documentación, además de monitorizar cómo la usa cada cliente.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-J1', 'BCK-04', 'Junior', 'mc', '¿Qué es una clave primaria?', null, 'Una columna (o varias) que identifica de forma única cada fila', array['Una contraseña de la base de datos', 'Un índice opcional', 'Una relación entre tablas']::text[], 'La clave foránea apunta a la primaria de otra tabla.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-J2', 'BCK-04', 'Junior', 'mc', '¿Qué hace un `JOIN` en SQL?', null, 'Combina filas de dos tablas relacionadas', array['Borra filas duplicadas', 'Crea una tabla nueva', 'Ordena resultados']::text[], 'INNER JOIN devuelve solo coincidencias; LEFT JOIN también las filas sin pareja de la izquierda.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-J3', 'BCK-04', 'Junior', 'fill', 'En Spring Data JPA, basta con extender ___ para tener findAll, save o deleteById.', null, 'JpaRepository', array['JpaEntity', 'CrudController', 'DataSource']::text[], 'Además puedes crear consultas por nombre de método, como findByEmail.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-J4', 'BCK-04', 'Junior', 'open', '¿Qué es un ORM y qué ventajas e inconvenientes tiene?', 'What is an ORM and what are its pros and cons?', null, '{}'::text[], null, null, null, 'maps objects to tables (JPA/Hibernate); pros: less boilerplate, portability, productivity; cons: hidden queries, N+1, performance issues, learning curve', 'An ORM, like Hibernate with JPA, maps Java objects to database tables, so you work with objects instead of writing all the SQL by hand. It saves a lot of boilerplate and speeds up development. The downside is that it hides the queries, so you can get performance problems like the N+1 problem if you don''t understand what it''s doing underneath.', 'Un ORM, como Hibernate con JPA, relaciona objetos Java con tablas de la base de datos, así que trabajas con objetos en lugar de escribir todo el SQL a mano. Ahorra mucho código repetitivo y acelera el desarrollo. El inconveniente es que oculta las consultas, y puedes tener problemas de rendimiento como el N+1 si no entiendes qué está haciendo por debajo.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-M1', 'BCK-04', 'Mid', 'mc', '¿Qué es el problema N+1?', null, 'Hacer una consulta para una lista y luego una consulta extra por cada elemento al acceder a sus relaciones', array['Tener N+1 tablas', 'Un error de clave primaria', 'Una consulta con N+1 columnas']::text[], 'Soluciones: JOIN FETCH, @EntityGraph o consultas por lotes.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-M2', 'BCK-04', 'Mid', 'mc', '¿Para qué sirve un índice?', null, 'Para acelerar búsquedas y ordenaciones, a costa de más espacio y escrituras algo más lentas', array['Para cifrar datos', 'Para hacer backups', 'Para evitar duplicados siempre']::text[], 'Un índice único sí evita duplicados, pero no es su función general.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-M3', 'BCK-04', 'Mid', 'mc', '¿Qué es el bloqueo optimista en JPA?', null, 'Un campo @Version que detecta si otro proceso modificó el registro y hace fallar la actualización', array['Bloquear toda la tabla', 'Confiar en que no habrá conflictos sin comprobar nada', 'Un tipo de índice']::text[], 'Ideal cuando los conflictos son poco frecuentes.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-M4', 'BCK-04', 'Mid', 'open', 'Una consulta va muy lenta en producción. ¿Cómo la investigarías?', 'A query is very slow in production. How would you investigate it?', null, '{}'::text[], null, null, null, 'reproduce and get the actual SQL (logs, slow query log); EXPLAIN/EXPLAIN ANALYZE; missing indexes, full scans; N+1 from ORM; data volume; fix: indexes, rewrite query, pagination, projections; measure', 'First I''d get the exact SQL, from the slow query log or the application logs, and run EXPLAIN ANALYZE to see the execution plan. Usually the cause is a missing index, a full table scan, or the ORM generating too many queries. Depending on what I find, I''d add an index, rewrite the query, fetch only the columns I need, or add pagination. Then I''d measure again with production-like data.', 'Primero obtendría el SQL exacto, desde el log de consultas lentas o los logs de la aplicación, y ejecutaría EXPLAIN ANALYZE para ver el plan de ejecución. Normalmente la causa es un índice que falta, un recorrido completo de la tabla o el ORM generando demasiadas consultas. Según lo que encuentre, añadiría un índice, reescribiría la consulta, traería solo las columnas necesarias o añadiría paginación. Después volvería a medir con datos parecidos a los de producción.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-S1', 'BCK-04', 'Senior', 'mc', '¿Qué nivel de aislamiento evita las lecturas no repetibles pero no siempre los fantasmas (según el estándar SQL)?', null, 'Repeatable Read', array['Read Uncommitted', 'Read Committed', 'Serializable']::text[], 'Cada motor lo implementa a su manera: en PostgreSQL, Repeatable Read también evita fantasmas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-S2', 'BCK-04', 'Senior', 'mc', '¿Cómo harías migraciones de esquema sin parar el servicio?', null, 'Cambios compatibles hacia atrás en varias fases (expand and contract) con Flyway o Liquibase', array['Parar el servicio cada vez', 'Modificar las tablas a mano en producción', 'Borrar y recrear la base de datos']::text[], 'Ejemplo: añadir columna nueva, escribir en ambas, migrar datos, y solo después borrar la vieja.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-S3', 'BCK-04', 'Senior', 'mc', '¿Cuándo elegirías una base de datos NoSQL en lugar de relacional?', null, 'Con patrones de acceso conocidos, gran escala o datos poco estructurados, donde no necesitas joins ni transacciones complejas', array['Siempre, es más moderna', 'Nunca', 'Cuando hay muchas relaciones entre entidades']::text[], 'Para la mayoría de aplicaciones de negocio, una relacional es la opción por defecto.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-04-S4', 'BCK-04', 'Senior', 'open', '¿Cómo escalarías una base de datos que se ha convertido en el cuello de botella?', 'How would you scale a database that has become the bottleneck?', null, '{}'::text[], null, null, null, 'measure first; optimize queries and indexes; caching (Redis); read replicas for reads; connection pooling; vertical scaling; partitioning; sharding as last resort; CQRS; archive old data', 'First I''d measure to know whether the problem is reads, writes or a few bad queries, and optimize those queries and indexes, which is often enough. Then a cache like Redis for frequent reads, and read replicas to spread the read load. Connection pooling tuned properly, and a bigger instance if needed. Partitioning or archiving old data helps with large tables. Sharding I''d keep as a last resort, because it adds a lot of complexity.', 'Primero mediría para saber si el problema son las lecturas, las escrituras o unas pocas consultas malas, y optimizaría esas consultas e índices, que a menudo es suficiente. Después, una caché como Redis para las lecturas frecuentes y réplicas de lectura para repartir esa carga. Un pool de conexiones bien ajustado y una instancia más grande si hace falta. Particionar o archivar los datos antiguos ayuda con tablas muy grandes. El sharding lo dejaría como último recurso, porque añade mucha complejidad.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-J1', 'BCK-05', 'Junior', 'mc', '¿Qué es una arquitectura en capas típica en un backend?', null, 'Controlador → servicio (lógica de negocio) → repositorio (acceso a datos)', array['Todo en el controlador', 'Base de datos → controlador → vista', 'Un solo archivo por aplicación']::text[], 'Cada capa tiene una responsabilidad y solo habla con la siguiente.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-J2', 'BCK-05', 'Junior', 'mc', '¿Qué es un microservicio?', null, 'Un servicio pequeño e independiente que se despliega por separado y se encarga de una parte del negocio', array['Una función de Java muy corta', 'Un servidor muy pequeño', 'Un tipo de base de datos']::text[], 'Cada uno suele tener su propia base de datos.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-J3', 'BCK-05', 'Junior', 'fill', 'El principio SOLID que dice que una clase debe tener una sola razón para cambiar es el de responsabilidad ___.', null, 'única', array['abierta', 'sustituible', 'invertida']::text[], 'Single Responsibility Principle.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-J4', 'BCK-05', 'Junior', 'open', '¿Qué diferencias hay entre un monolito y microservicios?', 'What are the differences between a monolith and microservices?', null, '{}'::text[], null, null, null, 'monolith: single deployable, simpler, easier transactions; microservices: independent deployment and scaling, team autonomy, but distributed complexity (network, consistency, observability)', 'A monolith is one application deployed as a single unit, which is simpler to develop, test and deploy at the beginning. Microservices split the application into independent services that can be deployed and scaled separately, which gives teams more autonomy. But they add the complexity of a distributed system: network failures, data consistency and much harder debugging.', 'Un monolito es una aplicación que se despliega como una sola unidad, lo que al principio es más sencillo de desarrollar, probar y desplegar. Los microservicios dividen la aplicación en servicios independientes que se despliegan y escalan por separado, lo que da más autonomía a los equipos. Pero añaden la complejidad de un sistema distribuido: fallos de red, consistencia de los datos y una depuración mucho más difícil.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-M1', 'BCK-05', 'Mid', 'mc', '¿Para qué sirve un circuit breaker (p. ej. Resilience4j)?', null, 'Para dejar de llamar temporalmente a un servicio que falla y evitar fallos en cascada', array['Para cifrar comunicaciones', 'Para balancear carga', 'Para guardar logs']::text[], 'Tras un tiempo deja pasar algunas llamadas de prueba para ver si se recuperó.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-M2', 'BCK-05', 'Mid', 'mc', '¿Qué ventaja tiene la comunicación asíncrona con colas o eventos (Kafka, RabbitMQ, SQS)?', null, 'Desacopla servicios y absorbe picos: el emisor no depende de que el receptor esté disponible en ese momento', array['Es siempre más rápida', 'Garantiza el orden sin configuración', 'Elimina la necesidad de bases de datos']::text[], 'A cambio, la consistencia es eventual y hay que gestionar reintentos y duplicados.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-M3', 'BCK-05', 'Mid', 'mc', '¿Qué es un API Gateway?', null, 'Un punto de entrada único que enruta peticiones a los servicios y aplica autenticación, límites o logs', array['Una base de datos', 'Un framework de tests', 'Un servidor de correo']::text[], 'Evita que los clientes conozcan la topología interna.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-M4', 'BCK-05', 'Mid', 'open', '¿Cómo gestionarías una operación que afecta a varios microservicios, como un pedido con pago y stock?', 'How would you handle an operation that spans several microservices, like an order with payment and stock?', null, '{}'::text[], null, null, null, 'no distributed transactions; saga pattern (choreography with events or orchestration); compensating actions; idempotent consumers; outbox pattern for reliable events; eventual consistency; monitoring', 'I''d avoid distributed transactions and use the saga pattern. The order service creates the order as pending and publishes an event; the payment and stock services react, and if one step fails, the others run compensating actions, like refunding the payment. To publish events reliably I''d use the outbox pattern, and make every consumer idempotent, because messages can arrive twice. The result is eventually consistent, so the UI must show intermediate states.', 'Evitaría las transacciones distribuidas y usaría el patrón saga. El servicio de pedidos crea el pedido como pendiente y publica un evento; los servicios de pago y de stock reaccionan y, si un paso falla, los demás ejecutan acciones de compensación, como devolver el pago. Para publicar los eventos de forma fiable usaría el patrón outbox, y haría idempotentes a todos los consumidores, porque un mensaje puede llegar dos veces. El resultado es consistente a la larga, así que la interfaz debe mostrar los estados intermedios.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-S1', 'BCK-05', 'Senior', 'mc', '¿Qué es el patrón Outbox?', null, 'Guardar el evento en una tabla dentro de la misma transacción que el cambio de negocio y publicarlo después de forma fiable', array['Enviar correos a la bandeja de salida', 'Un tipo de caché', 'Un balanceador']::text[], 'Evita el problema de guardar en base de datos pero no publicar el evento (o al revés).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-S2', 'BCK-05', 'Senior', 'mc', '¿Qué aporta Domain-Driven Design a la hora de dividir microservicios?', null, 'Usar bounded contexts del negocio para definir límites con sentido y un lenguaje común', array['Dividir por tablas de la base de datos', 'Un microservicio por clase', 'Dividir por capas técnicas']::text[], 'Dividir mal genera servicios muy acoplados: un ''monolito distribuido''.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-S3', 'BCK-05', 'Senior', 'mc', '¿Qué es CQRS?', null, 'Separar el modelo de escritura (comandos) del de lectura (consultas), que pueden optimizarse por separado', array['Un protocolo de red', 'Un tipo de cifrado', 'Un framework de Spring']::text[], 'Útil con lecturas muy distintas a las escrituras; añade complejidad si no hace falta.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-05-S4', 'BCK-05', 'Senior', 'open', '¿Partirías un monolito en microservicios? ¿Cómo lo harías?', 'Would you split a monolith into microservices? How would you do it?', null, '{}'::text[], null, null, null, 'only if there''s a real reason (scaling teams, deployment pain, scaling parts); modular monolith first; identify bounded contexts; strangler fig pattern extracting one piece at a time; data ownership; observability and CI/CD first; measure', 'Only if there''s a real problem to solve, like teams blocking each other or one part needing to scale differently. Often a well-structured modular monolith is enough. If we do it, I''d first identify the bounded contexts, then use the strangler fig pattern: extract one service at a time, starting with a well-isolated area, routing traffic to it gradually. Each service owns its data. And before starting, I''d make sure we have good CI/CD and observability, because otherwise distributed systems become very hard to operate.', 'Solo si hay un problema real que resolver, como equipos que se bloquean entre sí o una parte que necesita escalar de forma distinta. Muchas veces basta con un monolito modular bien estructurado. Si se hace, primero identificaría los bounded contexts y después aplicaría el patrón strangler fig: extraer un servicio cada vez, empezando por una zona bien aislada y desviando el tráfico poco a poco. Cada servicio es dueño de sus datos. Y antes de empezar me aseguraría de tener buen CI/CD y observabilidad, porque sin eso los sistemas distribuidos se vuelven muy difíciles de operar.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-J1', 'BCK-06', 'Junior', 'mc', '¿Qué librería se usa para tests unitarios en Java?', null, 'JUnit (normalmente con Mockito para los dobles)', array['Selenium', 'Postman', 'Maven']::text[], 'Spring Boot incluye spring-boot-starter-test con JUnit 5, Mockito y AssertJ.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-J2', 'BCK-06', 'Junior', 'mc', '¿Qué es la inyección SQL?', null, 'Un ataque que mete código SQL a través de datos de entrada mal tratados', array['Una forma de optimizar consultas', 'Un tipo de JOIN', 'Una migración']::text[], 'Se evita con consultas parametrizadas (JPA y JdbcTemplate lo hacen).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-J3', 'BCK-06', 'Junior', 'fill', 'Para crear un doble de una dependencia en Mockito se usa la anotación ___.', null, '@Mock', array['@Spy', '@Test', '@Bean']::text[], '@InjectMocks crea la clase a probar con los mocks inyectados.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-J4', 'BCK-06', 'Junior', 'open', '¿Cómo guardarías las contraseñas de los usuarios?', 'How would you store users'' passwords?', null, '{}'::text[], null, null, null, 'never plain text or reversible encryption; slow adaptive hashing with salt (bcrypt, Argon2); Spring Security PasswordEncoder; never log them', 'Never in plain text, and not with reversible encryption either. I''d hash them with a slow algorithm designed for passwords, like bcrypt or Argon2, which includes a random salt. In Spring this is easy with the PasswordEncoder from Spring Security. And I''d make sure passwords are never written to the logs.', 'Nunca en texto plano, ni con un cifrado reversible. Las guardaría con un algoritmo de hash lento pensado para contraseñas, como bcrypt o Argon2, que incluye una sal aleatoria. En Spring es sencillo con el PasswordEncoder de Spring Security. Y me aseguraría de que las contraseñas nunca se escriben en los logs.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-M1', 'BCK-06', 'Mid', 'mc', '¿Para qué sirve `@WebMvcTest`?', null, 'Para testear solo la capa web (controladores) con MockMvc, sin levantar todo el contexto', array['Para tests E2E con navegador', 'Para testear la base de datos', 'Para tests de carga']::text[], '@DataJpaTest hace lo mismo para la capa de repositorios.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-M2', 'BCK-06', 'Mid', 'mc', '¿Qué aportan los Testcontainers?', null, 'Levantar dependencias reales (PostgreSQL, Kafka…) en Docker durante los tests de integración', array['Tests más rápidos que los unitarios', 'Sustituyen a JUnit', 'Son mocks de bases de datos']::text[], 'Más realista que una base de datos en memoria como H2.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-M3', 'BCK-06', 'Mid', 'mc', '¿Qué contiene un JWT y qué NO debe contener?', null, 'Claims firmados (usuario, roles, expiración); no debe llevar datos sensibles porque el payload solo está codificado, no cifrado', array['Contraseñas cifradas', 'La clave privada', 'Nada, es aleatorio']::text[], 'Cualquiera puede decodificarlo; la firma solo garantiza que no se ha modificado.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-M4', 'BCK-06', 'Mid', 'open', '¿Cómo protegerías una API REST con Spring Security?', 'How would you secure a REST API with Spring Security?', null, '{}'::text[], null, null, null, 'authentication with OAuth2/JWT (resource server); stateless; authorization by roles/scopes at endpoint and method level; HTTPS; CORS config; input validation; rate limiting; security headers; no sensitive data in errors', 'I''d configure the API as an OAuth2 resource server that validates JWT tokens from an identity provider, stateless, without sessions. Authorization by roles or scopes, at endpoint level and with method security for finer rules. HTTPS everywhere, a strict CORS configuration, input validation, and rate limiting. And error responses that don''t leak internal details.', 'Configuraría la API como un resource server de OAuth2 que valida tokens JWT de un proveedor de identidad, sin estado y sin sesiones. Autorización por roles o scopes, a nivel de endpoint y con seguridad en métodos para las reglas más finas. HTTPS en todo, una configuración de CORS estricta, validación de las entradas y límite de peticiones. Y respuestas de error que no revelen detalles internos.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-S1', 'BCK-06', 'Senior', 'mc', '¿Qué son los contract tests (p. ej. Pact, Spring Cloud Contract)?', null, 'Tests que verifican que proveedor y consumidor de una API cumplen el contrato acordado, sin levantar todo el sistema', array['Tests legales', 'Tests de carga', 'Tests manuales']::text[], 'Detectan cambios que rompen a otros servicios antes del despliegue.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-S2', 'BCK-06', 'Senior', 'mc', '¿Qué es el OWASP Top 10?', null, 'Una lista de los riesgos de seguridad más críticos en aplicaciones web', array['Un ranking de frameworks', 'Una certificación de Java', 'Un tipo de firewall']::text[], 'Incluye control de acceso roto, inyección, fallos criptográficos…', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-S3', 'BCK-06', 'Senior', 'mc', '¿Qué estrategia usarías para detectar dependencias vulnerables?', null, 'Escaneo automático en el pipeline (Dependabot, OWASP Dependency-Check, Snyk) y actualizaciones regulares', array['Revisarlas a mano una vez al año', 'No usar dependencias', 'Confiar en que Maven lo hace solo']::text[], 'La mayoría del código de una app son dependencias de terceros.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('BCK-06-S4', 'BCK-06', 'Senior', 'open', '¿Cómo integrarías la seguridad en el ciclo de desarrollo de un equipo backend?', 'How would you integrate security into a backend team''s development cycle?', null, '{}'::text[], null, null, null, 'shift-left: threat modeling for new features; secure coding guidelines; SAST and dependency scanning in CI; secrets scanning; DAST in staging; code review checklist; least privilege; security training; incident response; pentests', 'I''d shift security left. For new features, a quick threat modeling session. In the pipeline: static analysis, dependency and secret scanning, and dynamic tests against staging. Security items in the code review checklist, least privilege for every service and database user, and regular training for the team. Plus periodic penetration tests and a clear plan for responding to incidents.', 'Llevaría la seguridad al principio del proceso. Para cada funcionalidad nueva, una sesión rápida de análisis de amenazas. En el pipeline: análisis estático, revisión de dependencias y de secretos, y pruebas dinámicas contra preproducción. Puntos de seguridad en la checklist de code review, mínimo privilegio para cada servicio y usuario de base de datos, y formación periódica para el equipo. Además, tests de penetración periódicos y un plan claro de respuesta ante incidentes.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-J1', 'COM-01', 'Junior', 'mc', '¿Qué significa STAR?', null, 'Situation, Task, Action, Result (Situación, Tarea, Acción, Resultado)', array['Skills, Tools, Achievements, Results', 'Situation, Team, Approach, Review', 'Story, Task, Action, Reflection']::text[], 'Es la estructura que esperan en las preguntas de comportamiento: "Tell me about a time when…".', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-J2', 'COM-01', 'Junior', 'order', 'Ordena esta respuesta STAR', null, 'En las prácticas, el formulario de registro tenía muchos abandonos. | Me pidieron averiguar por qué y proponer una mejora. | Analicé los errores de validación y simplifiqué el formulario de 9 a 5 campos. | Los registros completados subieron un 30% el mes siguiente.', '{}'::text[], 'Situación → Tarea → Acción → Resultado. Cierra siempre con un resultado medible.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-J3', 'COM-01', 'Junior', 'mc', '¿Cuál es la mejor estructura para "Tell me about yourself"?', null, 'Presente → pasado → futuro', array['Infancia → estudios → aficiones', 'Todo el CV, trabajo por trabajo', 'Fortalezas → debilidades → salario']::text[], 'Quién eres hoy, cómo llegaste y por qué este puesto encaja. Entre 60 y 90 segundos.', 'I''m a junior developer who recently finished my training in web development. During my internship I worked on a real product with a team, which taught me a lot about code reviews and teamwork. Now I''m looking for a team where I can keep learning and start contributing from the first weeks.', 'Soy desarrollador junior y acabo de terminar mi formación en desarrollo web. En las prácticas trabajé en un producto real con un equipo, lo que me enseñó mucho sobre code reviews y trabajo en equipo. Ahora busco un equipo donde seguir aprendiendo y empezar a aportar desde las primeras semanas.', null, null, null, 'pending', true, '¿Cuál es la mejor estructura para responder a «Háblame de ti»?', null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-J4', 'COM-01', 'Junior', 'open', 'Háblame de ti.', 'Tell me about yourself.', null, '{}'::text[], null, null, null, 'current situation and training; relevant projects or internship; skills; motivation; why this role; 60-90 seconds', 'I''m a web developer who recently finished my training, focused on frontend. During my internship I worked on a real application with a small team, building forms and connecting them to an API, and I learned a lot about working with Git and code reviews. In my free time I''ve built a couple of personal projects to practise. Now I''m looking for my first full-time role in a team where I can keep growing, and this position fits exactly what I want to do.', 'Soy desarrollador web y acabo de terminar mi formación, centrada en frontend. En las prácticas trabajé en una aplicación real con un equipo pequeño, creando formularios y conectándolos a una API, y aprendí mucho sobre trabajar con Git y las code reviews. En mi tiempo libre he hecho un par de proyectos personales para practicar. Ahora busco mi primer trabajo a tiempo completo en un equipo donde seguir creciendo, y este puesto encaja justo con lo que quiero hacer.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-M1', 'COM-01', 'Mid', 'mc', '¿Qué respuesta a "What''s your greatest weakness?" funciona mejor?', null, 'I sometimes go too deep into details, so now I timebox research and check in with the team earlier.', array['I''m a perfectionist and I work too hard.', 'I don''t really have weaknesses.', 'I''m not very good at working in teams.']::text[], 'Una debilidad real pero no crítica para el puesto, más lo que haces para mejorarla.', 'Sometimes I go too deep into details before asking for help. Now I timebox my research, and if I''m stuck after an hour or so, I check in with the team. It''s made me much faster.', 'A veces profundizo demasiado en los detalles antes de pedir ayuda. Ahora me pongo un límite de tiempo y, si sigo atascado tras una hora, lo comento con el equipo. Me ha hecho mucho más rápido.', null, null, null, 'pending', true, 'Te preguntan «¿Cuál es tu mayor debilidad?». ¿Qué respuesta funciona mejor?', 'A veces profundizo demasiado en los detalles, así que ahora me pongo un límite de tiempo y consulto antes con el equipo.', array['Soy perfeccionista y trabajo demasiado.', 'La verdad es que no tengo debilidades.', 'No se me da muy bien trabajar en equipo.']::text[], null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-M2', 'COM-01', 'Mid', 'mc', 'Te preguntan por un conflicto con un compañero. ¿Qué enfoque es mejor?', null, 'Contar un desacuerdo real, cómo lo hablasteis con datos y cómo se resolvió, sin culpar a nadie', array['Decir que nunca has tenido conflictos', 'Explicar por qué el compañero estaba equivocado', 'Cambiar de tema']::text[], 'Buscan madurez: escuchar, argumentar con datos y priorizar el objetivo del equipo.', 'In a project, a colleague and I disagreed about how to structure the state. Instead of arguing, we each wrote down pros and cons and built a quick proof of concept. We went with his approach, with one idea from mine, and it worked well. Since then we''ve worked really well together.', 'En un proyecto, un compañero y yo no estábamos de acuerdo en cómo estructurar el estado. En vez de discutir, apuntamos pros y contras y montamos una prueba de concepto rápida. Elegimos su enfoque con una idea del mío y funcionó bien. Desde entonces trabajamos muy bien juntos.', null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-M3', 'COM-01', 'Mid', 'fill', 'En una respuesta STAR, habla de lo que hiciste ___, no solo de lo que hizo el equipo.', null, 'tú', array['el jefe', 'el cliente', 'la empresa']::text[], 'Di "I" más que "we": quieren saber cuál fue tu aportación.', null, null, null, null, null, 'pending', true, null, null, null, 'Habla en primera persona («yo propuse», «yo implementé») más que en plural: quieren saber cuál fue tu aportación.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-M4', 'COM-01', 'Mid', 'open', 'Cuéntame una situación en la que cometiste un error en el trabajo y cómo lo gestionaste.', 'Tell me about a time you made a mistake at work and how you handled it.', null, '{}'::text[], null, null, null, 'STAR; real but not catastrophic mistake; take ownership; how it was fixed quickly; communication; lesson learned and process change', 'In one release I deployed a change without testing it on a small screen, and the checkout button was hidden on some mobile phones. As soon as support reported it, I told my lead, reverted the change and fixed it within an hour. Afterwards I added mobile viewports to our visual tests, so it couldn''t happen again. I learned to own mistakes quickly and to fix the process, not just the bug.', 'En una release desplegué un cambio sin probarlo en pantallas pequeñas, y el botón de pago quedaba oculto en algunos móviles. En cuanto soporte lo avisó, se lo dije a mi responsable, revertí el cambio y lo arreglé en menos de una hora. Después añadí tamaños de móvil a nuestros tests visuales para que no pudiera repetirse. Aprendí a asumir los errores rápido y a arreglar el proceso, no solo el fallo.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-S1', 'COM-01', 'Senior', 'mc', 'Te preguntan cómo has ayudado a crecer a otras personas. ¿Qué incluyes?', null, 'Un ejemplo concreto de mentoring con acciones (pair programming, feedback, delegar retos) y su resultado', array['Que siempre ayudas cuando te preguntan', 'Que el crecimiento es responsabilidad de cada uno', 'Una lista de cursos que recomiendas']::text[], 'En perfiles senior buscan impacto en el equipo, no solo en el código.', 'I mentored a junior developer who was struggling with RxJS. We did pair programming twice a week, I gave her small but real tasks, and I reviewed her pull requests with explanations, not just corrections. After three months she was leading a feature on her own.', 'Fui mentor de una desarrolladora junior a la que le costaba RxJS. Hacíamos pair programming dos veces por semana, le daba tareas pequeñas pero reales y revisaba sus pull requests explicando, no solo corrigiendo. A los tres meses lideraba ella sola una funcionalidad.', null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-S2', 'COM-01', 'Senior', 'mc', '¿Cómo respondes a "Tell me about a technical decision you regret"?', null, 'Con una decisión real, por qué tenía sentido entonces, qué aprendiste y qué harías distinto', array['Diciendo que nunca te arrepientes de nada', 'Culpando al equipo de producto', 'Con un error trivial sin consecuencias']::text[], 'Demuestra criterio y capacidad de aprender, que es lo que se espera de un senior.', 'We added a global state library very early in a project, when the app was still small. It slowed the team down with a lot of boilerplate. Now I start with the simplest option and only add complexity when there''s a clear need.', 'Añadimos una librería de estado global muy pronto en un proyecto, cuando la app aún era pequeña. Ralentizó al equipo con mucho código repetitivo. Ahora empiezo por la opción más sencilla y solo añado complejidad cuando hay una necesidad clara.', null, null, null, 'pending', true, '¿Cómo respondes a «Cuéntame una decisión técnica de la que te arrepientas»?', null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-S3', 'COM-01', 'Senior', 'fill', 'Para un senior, una buena respuesta STAR muestra el impacto en el ___, no solo en el código.', null, 'negocio', array['framework', 'IDE', 'linter']::text[], 'Habla de usuarios, costes, tiempos de entrega o ventas cuando puedas.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-01-S4', 'COM-01', 'Senior', 'open', 'Cuéntame un proyecto del que estés especialmente orgulloso.', 'Tell me about a project you''re particularly proud of.', null, '{}'::text[], null, null, null, 'context and business goal; own role and leadership; technical decisions and trade-offs; challenges; measurable impact; what they learned; team', 'I''m especially proud of a migration I led for a banking client. The app was slow and hard to change, and the business wanted to release features faster. I proposed migrating it gradually instead of rewriting it, defined the target architecture with the team and set up the pipeline and tests. In six months we cut load time by half and went from monthly releases to weekly ones, without stopping feature work.', 'Estoy especialmente orgulloso de una migración que lideré para un cliente bancario. La aplicación era lenta y difícil de cambiar, y el negocio quería sacar funcionalidades más rápido. Propuse migrarla poco a poco en lugar de reescribirla, definí con el equipo la arquitectura objetivo y monté el pipeline y los tests. En seis meses redujimos el tiempo de carga a la mitad y pasamos de releases mensuales a semanales, sin parar el desarrollo de funcionalidades.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-J1', 'COM-02', 'Junior', 'mc', '"Why should we hire you?" (¿por qué deberíamos contratarte?) ¿Qué enfoque es mejor?', null, 'Unir dos o tres cosas concretas tuyas con lo que pide la oferta, y tu ganas de aprender', array['Decir que necesitas el trabajo', 'Decir que eres el mejor candidato sin más', 'Hablar de lo que no te gusta de tu trabajo actual']::text[], 'Relaciona tus fortalezas con las necesidades del puesto.', 'You''re looking for someone who knows Angular and can learn fast. I''ve built two projects with Angular and TypeScript, I''m used to working with Git in a team from my internship, and I''m someone who asks questions and learns quickly.', 'Buscáis a alguien que conozca Angular y aprenda rápido. He hecho dos proyectos con Angular y TypeScript, estoy acostumbrado a trabajar con Git en equipo desde las prácticas y soy alguien que pregunta y aprende rápido.', null, null, null, 'pending', true, '«¿Por qué deberíamos contratarte?» ¿Qué enfoque es mejor?', null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-J2', 'COM-02', 'Junior', 'mc', 'Te preguntan algo técnico que no sabes. ¿Qué haces?', null, 'Reconocerlo con naturalidad, explicar cómo lo averiguarías o razonar en voz alta lo que sí sabes', array['Inventarte la respuesta', 'Quedarte en silencio', 'Decir que no es importante']::text[], 'Inventar se nota y resta mucho; razonar suma.', 'I haven''t worked with that directly, but I''d guess it works similarly to X. In a real situation, I''d check the official documentation and try a small example.', 'No he trabajado con eso directamente, pero imagino que funciona de forma parecida a X. En una situación real, miraría la documentación oficial y probaría con un ejemplo pequeño.', null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-J3', 'COM-02', 'Junior', 'mc', '¿Qué buena pregunta puedes hacer tú al final?', null, 'What does a typical day look like for someone in this role?', array['How many vacation days do I get?', 'So, what does your company do?', 'No, I don''t have any questions.']::text[], 'Demuestra interés real y te da información para decidir.', 'What does a typical day look like for someone in this role? And how do new people get support during their first months?', '¿Cómo es un día normal en este puesto? ¿Y cómo apoyáis a las personas nuevas durante los primeros meses?', null, null, null, 'pending', true, null, '¿Cómo es un día normal para alguien en este puesto?', array['¿Cuántos días de vacaciones tendría?', 'Entonces, ¿a qué se dedica vuestra empresa?', 'No, no tengo ninguna pregunta.']::text[], null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-J4', 'COM-02', 'Junior', 'open', '¿Dónde te ves dentro de cinco años?', 'Where do you see yourself in five years?', null, '{}'::text[], null, null, null, 'realistic growth path; mastering the role first; more responsibility (mid/senior, mentoring); link to the company; ambition without seeming to leave soon', 'In five years I''d like to be a solid mid or senior developer, someone the team can trust with complex features. First I want to master the basics in a real product, and then take on more responsibility, like making technical decisions and helping new colleagues. I''d love to do that growth here, in a company where I can learn from experienced people.', 'Dentro de cinco años me gustaría ser un desarrollador mid o senior sólido, alguien en quien el equipo pueda confiar para funcionalidades complejas. Primero quiero dominar lo básico en un producto real y después asumir más responsabilidad, como tomar decisiones técnicas y ayudar a los compañeros nuevos. Me encantaría hacer ese camino aquí, en una empresa donde pueda aprender de gente con experiencia.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-M1', 'COM-02', 'Mid', 'mc', '"I see a gap in your recent experience." (veo un hueco en tu experiencia reciente) ¿Cómo lo enfocas?', null, 'Breve y sincero, y luego centrarte en lo que hiciste para seguir en forma y por qué estás listo ahora', array['Cambiar de tema rápido', 'Explicar con detalle todo lo que salió mal', 'Echar la culpa a tu anterior empresa']::text[], 'Una frase de contexto, sin dramas, y enseguida a lo positivo.', 'Yes, my last project had very little development work, so I decided to use that time to retrain. I''ve been learning new technologies and catching up with the latest versions of my stack. Now I''m really keen to get back into a team and build things.', 'Sí, mi último proyecto tenía muy poco desarrollo, así que decidí aprovechar ese tiempo para formarme. He estado aprendiendo tecnologías nuevas y poniéndome al día con las últimas versiones de mi stack. Ahora tengo muchas ganas de volver a un equipo y construir cosas.', null, null, null, 'pending', true, '«Veo un hueco en tu experiencia reciente.» ¿Cómo lo enfocas?', null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-M2', 'COM-02', 'Mid', 'mc', '"Why did you leave your last job?" (¿por qué dejaste tu último trabajo?) ¿Qué respondes?', null, 'I wanted more hands-on coding and growth, and that wasn''t possible on that project.', array['My manager was terrible.', 'Honestly, I just needed any job.', 'I got bored.']::text[], 'Nunca hables mal de una empresa anterior. Enmárcalo en lo que buscas, no en lo que huyes.', 'I was on a project where I wasn''t getting much hands-on development, and I want to keep growing as a developer. So I''m looking for a team where I can build features every day and learn from good engineers.', 'Estaba en un proyecto donde apenas hacía desarrollo, y quiero seguir creciendo como desarrollador. Por eso busco un equipo donde pueda construir funcionalidades cada día y aprender de buenos ingenieros.', null, null, null, 'pending', true, '«¿Por qué dejaste tu último trabajo?» ¿Qué respondes?', 'Quería programar más y seguir creciendo, y en ese proyecto no era posible.', array['Mi jefe era horrible.', 'Sinceramente, necesitaba cualquier trabajo.', 'Me aburría.']::text[], null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-M3', 'COM-02', 'Mid', 'mc', '"What are your salary expectations?" (¿qué expectativas salariales tienes?) ¿Cómo lo enfocas?', null, 'Dar un rango investigado para el puesto y la ciudad, y mostrar algo de flexibilidad', array['Decir "lo que os parezca justo"', 'Negarte a responder', 'Decir una cifra muy por encima del mercado']::text[], 'Un rango investigado te protege de pedir poco y no cierra la puerta.', 'Based on what I''ve seen for similar roles, I''m looking for something between X and Y a year. But I''m flexible, it depends on the whole package and the remote options.', 'Por lo que he visto en puestos similares, busco algo entre X e Y al año. Pero soy flexible: depende del paquete completo y de las opciones de teletrabajo. (Sustituye X e Y por tu rango real.)', null, null, null, 'pending', true, '«¿Qué expectativas salariales tienes?» ¿Cómo lo enfocas?', null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-M4', 'COM-02', 'Mid', 'open', '¿Por qué quieres trabajar aquí?', 'Why do you want to work here?', null, '{}'::text[], null, null, null, 'specific things about the company (product, stack, clients, culture); link to own experience; what they would contribute; avoid generic praise', 'I''ve been reading about your projects, and what caught my attention is that you build large applications for clients in sectors I already know. That''s where I have the most experience, so I think I can contribute from day one. I also like that you work with a modern stack, which is the direction I''ve been studying. And I''m looking for a team that cares about code quality, which is what I''ve heard about you.', 'He estado leyendo sobre vuestros proyectos y me ha llamado la atención que desarrolláis aplicaciones grandes para clientes de sectores que ya conozco. Ahí es donde tengo más experiencia, así que creo que puedo aportar desde el primer día. También me gusta que trabajéis con un stack moderno, que es justo hacia donde he estado formándome. Y busco un equipo al que le importe la calidad del código, que es lo que he oído de vosotros.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-S1', 'COM-02', 'Senior', 'mc', 'Tienes otra oferta y te preguntan si estás en otros procesos. ¿Qué haces?', null, 'Ser sincero sin dar detalles innecesarios, y dejar claro por qué te interesa especialmente este puesto', array['Mentir y decir que no', 'Usarlo para presionar de forma agresiva', 'Negarte a responder']::text[], 'La transparencia genera confianza y puede acelerar el proceso.', 'Yes, I''m in a couple of other processes, one of them at an advanced stage. But this role is my first choice because of the product and the team, so I''d be happy to move forward quickly if it works for you.', 'Sí, estoy en un par de procesos más, uno de ellos bastante avanzado. Pero este puesto es mi primera opción por el producto y el equipo, así que me encantaría avanzar rápido si os encaja.', null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-S2', 'COM-02', 'Senior', 'mc', '"How do you handle disagreement with your manager about a technical decision?" ¿Qué enfoque es mejor?', null, 'Plantear tu postura con datos y riesgos, escuchar sus motivos y, si se decide lo contrario, comprometerte con la decisión', array['Hacer lo que tú crees sin decir nada', 'Escalar directamente a su jefe', 'Aceptar siempre sin opinar']::text[], 'Es el principio de "disagree and commit".', 'I''d explain my concerns with data, for example the risks or the cost of each option, and listen to the reasons behind the decision. If we still go another way, I commit to it fully, and we agree on a point to review whether it''s working.', 'Explicaría mis dudas con datos, por ejemplo los riesgos o el coste de cada opción, y escucharía los motivos de la decisión. Si aun así se elige otro camino, me comprometo del todo y acordamos un momento para revisar si está funcionando.', null, null, null, 'pending', true, '«¿Cómo gestionas un desacuerdo con tu responsable sobre una decisión técnica?» ¿Qué enfoque es mejor?', null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-S3', 'COM-02', 'Senior', 'mc', '"Why are you looking for a change after so many years?" ¿Qué respuesta funciona mejor?', null, 'Hablar de lo que buscas ahora (impacto, retos, liderazgo) y por qué este puesto lo ofrece', array['Decir que estás quemado', 'Quejarte de tu empresa actual', 'Decir que es solo por dinero']::text[], 'Enfoque positivo y orientado al futuro.', 'I''ve learned a lot in my current company, but I feel I''ve reached a point where I want a bigger impact, for example shaping the architecture of a product from the start. This role offers exactly that.', 'He aprendido mucho en mi empresa actual, pero siento que he llegado a un punto en el que quiero más impacto, por ejemplo definir la arquitectura de un producto desde el principio. Este puesto me ofrece justo eso.', null, null, null, 'pending', true, '«¿Por qué buscas un cambio después de tantos años?» ¿Qué respuesta funciona mejor?', null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-02-S4', 'COM-02', 'Senior', 'open', '¿Cuál dirías que es tu estilo de liderazgo técnico?', 'How would you describe your technical leadership style?', null, '{}'::text[], null, null, null, 'lead by example and context; explain the why; involve the team in decisions; delegate with support; code reviews as teaching; protect focus; balance quality and delivery; concrete example', 'I''d say I lead by giving context rather than orders: I explain why we make a decision and involve the team, especially the people who will build it. I delegate challenging work with support, and I use code reviews to teach, not just to approve. I try to balance quality with delivering on time. For example, in my last project I set up architecture discussions every two weeks, and the team started proposing improvements on their own.', 'Diría que lidero dando contexto más que órdenes: explico por qué tomamos una decisión e implico al equipo, sobre todo a quienes la van a construir. Delego trabajo con retos, pero con apoyo, y uso las code reviews para enseñar, no solo para aprobar. Intento equilibrar la calidad con entregar a tiempo. Por ejemplo, en mi último proyecto organicé conversaciones de arquitectura cada dos semanas y el equipo empezó a proponer mejoras por su cuenta.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-J1', 'COM-03', 'Junior', 'mc', '"Actualmente trabajo con Angular" →', null, 'I''m currently working with Angular.', array['Actually I work with Angular.', 'Actually I''m working in Angular.', 'In the actual moment I work with Angular.']::text[], 'Actually = en realidad. Actualmente = currently / at the moment.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-J2', 'COM-03', 'Junior', 'fill', 'I''ve been working with Angular ___ 2019.', null, 'since', array['for', 'from', 'during']::text[], 'Since + punto de inicio (since 2019). For + duración (for five years).', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-J3', 'COM-03', 'Junior', 'mc', 'No has entendido la pregunta. Dices:', null, 'Sorry, could you rephrase that, please?', array['What?', 'Repeat.', 'I no understand.']::text[], 'Pedir que lo reformulen es normal y profesional.', 'Sorry, could you rephrase that, please? Just to make sure: do you mean how I would build it, or how I would test it?', 'Perdona, ¿podrías reformularlo? Solo para asegurarme: ¿te refieres a cómo lo construiría o a cómo lo testearía?', null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-J4', 'COM-03', 'Junior', 'open', 'Describe el último proyecto en el que trabajaste.', 'Describe the last project you worked on.', null, '{}'::text[], null, null, null, 'what the project was and for whom; team; your role and tasks; technologies; one challenge; past tenses used correctly', 'My last project was a web application for a bank''s internal team. We were five developers, and I was responsible for the frontend of the reporting module. I built the screens with Angular, connected them to a REST API, and wrote unit tests. The biggest challenge was showing large tables quickly, which I solved with pagination and virtual scrolling.', 'Mi último proyecto fue una aplicación web para un equipo interno de un banco. Éramos cinco desarrolladores y yo me encargaba del frontend del módulo de informes. Construí las pantallas con Angular, las conecté a una API REST y escribí tests unitarios. El mayor reto fue mostrar tablas grandes con rapidez, y lo resolví con paginación y virtual scroll.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-M1', 'COM-03', 'Mid', 'mc', '"Asistí a la reunión de planificación" →', null, 'I attended the planning meeting.', array['I assisted the planning meeting.', 'I assisted to the planning meeting.', 'I went in the planning meeting.']::text[], 'Attend = asistir (estar presente). Assist = ayudar.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-M2', 'COM-03', 'Mid', 'mc', '"Me encargaba del módulo de pagos" →', null, 'I was in charge of the payments module.', array['I was charged of the payments module.', 'I encharged the payments module.', 'I was encharged of the payments module.']::text[], 'In charge of / responsible for. "Charge" a secas es cobrar o cargar.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-M3', 'COM-03', 'Mid', 'mc', 'Necesitas unos segundos para pensar. ¿Qué frase es la mejor?', null, 'That''s a good question. Let me think about it for a second.', array['Eh… eh… wait.', 'I don''t know.', 'Next question, please.']::text[], 'Pensar en voz alta está bien visto en entrevistas técnicas.', 'That''s a good question. Let me think about it for a second… OK, so the way I see it is…', 'Buena pregunta. Déjame pensarlo un segundo… Vale, tal y como yo lo veo…', null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-M4', 'COM-03', 'Mid', 'open', 'Cuéntame un reto técnico que hayas resuelto.', 'Tell me about a technical challenge you solved.', null, '{}'::text[], null, null, null, 'STAR; specific technical problem; what they personally did; concrete technologies; measurable result; correct natural English', 'In a banking project, our transaction list became very slow once clients had thousands of movements. My task was to fix it without changing the API. I profiled it and saw that every keystroke in the filter re-rendered the whole list. I optimized the change detection, added virtual scrolling and debounced the filter. Rendering time went from about two seconds to under two hundred milliseconds.', 'En un proyecto bancario, la lista de movimientos se volvió muy lenta cuando los clientes tenían miles de operaciones. Mi tarea era arreglarlo sin cambiar la API. Lo analicé y vi que cada pulsación en el filtro volvía a pintar toda la lista. Optimicé la detección de cambios, añadí virtual scroll y un debounce al filtro. El tiempo de pintado pasó de unos dos segundos a menos de doscientos milisegundos.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-S1', 'COM-03', 'Senior', 'mc', 'Para matizar una opinión de forma profesional, ¿qué frase suena mejor?', null, 'I see your point, but I''d push back a little on that, because…', array['You''re wrong.', 'No, no, no.', 'That''s a stupid idea.']::text[], 'En inglés profesional se suaviza el desacuerdo: "I''d push back a bit", "I see it slightly differently".', 'I see your point, but I''d push back a little on that, because in my experience it adds complexity we don''t need yet.', 'Entiendo lo que dices, pero no estoy del todo de acuerdo, porque en mi experiencia añade una complejidad que todavía no necesitamos.', null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-S2', 'COM-03', 'Senior', 'mc', '"Llevé a cabo la migración" →', null, 'I led / carried out the migration.', array['I realized the migration.', 'I made the migration realized.', 'I carried the migration.']::text[], 'Realize = darse cuenta. Para "realizar" usa carry out, do, lead o implement.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-S3', 'COM-03', 'Senior', 'fill', 'If I ___ known about the issue earlier, I would have fixed it before the release.', null, 'had', array['have', 'would', 'was']::text[], 'Tercer condicional: If + had + participio, would have + participio.', null, null, null, null, null, 'pending', true, null, null, null, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, level, type, prompt, prompt_en, correct, wrong, explanation, say_en, say_es, keys, model_en, model_es, status, active, es_prompt, es_correct, es_wrong, es_explanation) values ('COM-03-S4', 'COM-03', 'Senior', 'open', 'Explícame un concepto técnico complejo como si yo no fuera técnico.', 'Explain a complex technical concept to me as if I weren''t technical.', null, '{}'::text[], null, null, null, 'pick a real concept (e.g. caching, APIs, load balancing); simple analogy; avoid jargon; check understanding; why it matters for the business; clear structure', 'Let me explain caching. Imagine a library where people keep asking for the same book. Instead of going to the basement every time, the librarian keeps a copy on the front desk. That''s a cache: we keep frequently used data close, so the answer is much faster. The trade-off is that the copy on the desk might be slightly out of date, so we decide how often to refresh it. For the business, it means faster pages and lower server costs.', 'Te explico la caché. Imagina una biblioteca donde la gente pide una y otra vez el mismo libro. En lugar de bajar al sótano cada vez, el bibliotecario deja una copia en el mostrador. Eso es una caché: guardamos cerca los datos que se usan mucho, así la respuesta es mucho más rápida. El inconveniente es que la copia del mostrador puede estar algo desactualizada, así que decidimos cada cuánto renovarla. Para el negocio significa páginas más rápidas y menos coste de servidores.', 'pending', true, null, null, null, null) on conflict (id) do nothing;
